import subprocess, random, os, re, sys, json
env = dict(os.environ); env["PATH"] = "/tmp/fakebin:" + env["PATH"]
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 200
keys_bar = ["separator", "background", "statusline"]
ws = ["focused_workspace", "inactive_workspace", "urgent_workspace"]
win = ["focused", "focused_inactive", "unfocused", "urgent"]
results = {}
for it in range(N):
    cols = set()
    while len(cols) < 28:
        cols.add("#%06X" % random.randrange(0, 1 << 24))
    cols = list(cols)
    i = 0
    lines = ["bar {", "  colors {"]
    for k in keys_bar:
        lines.append(f"    {k} {cols[i]}"); i += 1
    for k in ws:
        lines.append(f"    {k} {cols[i]} {cols[i+1]} {cols[i+2]}"); i += 3
    lines += ["  }", "}"]
    for k in win:
        lines.append(f"client.{k} {cols[i]} {cols[i+1]} {cols[i+2]} {cols[i+3]}"); i += 4
    with open("/tmp/t/ds/cfg.conf", "w") as f:
        f.write("\n".join(lines) + "\n")
