        print("ERR", r.stderr); continue
    in_colors = False
    for line in r.stdout.splitlines():
        if line.startswith("colors:"):
            in_colors = True; continue
        if in_colors:
            if not line.startswith("  "):
                break
            m = re.match(r'  ([a-z]+)(?:-\d+)?: "(#[0-9A-F]{6})"', line)
            if not m:
                print("UNPARSED", line); continue
            results[m.group(2)] = m.group(1)
