import subprocess, os, re, sys
env = dict(os.environ); env["PATH"] = "/tmp/fakebin:" + env["PATH"]
keys_bar = ["separator", "background", "statusline"]
ws = ["focused_workspace", "inactive_workspace", "urgent_workspace"]
win = ["focused", "focused_inactive", "unfocused", "urgent"]
def name_colors(cols):
    """cols: list of hex strings (distinct, up to 28). returns dict hex->basename"""
    cols = list(dict.fromkeys(cols))
    out = {}
    for chunk_start in range(0, len(cols), 28):
        chunk = cols[chunk_start:chunk_start+28]
        while len(chunk) < 28:
            # pad with duplicates of first (duplicates are fine, they map to same name)
            chunk.append(chunk[0])
        i = 0
        lines = ["bar {", "  colors {"]
        for k in keys_bar:
            lines.append(f"    {k} {chunk[i]}"); i += 1
        for k in ws:
            lines.append(f"    {k} {chunk[i]} {chunk[i+1]} {chunk[i+2]}"); i += 3
