                    break
                m = re.match(r'  ([a-z]+)(?:-\d+)?: "?(#?[0-9A-Z]+)"?', line)
                out[m.group(2)] = m.group(1)
    return out
if __name__ == "__main__":
    cols = sys.argv[1:]
    res = name_colors(cols)
    for c in cols:
