{"command":"cd /workspace && cat > src/yaml.rs <<'EOF'
//! A small YAML reader/writer that covers the subset of YAML used by theme
//! files.  The data model mirrors the one used by the classic `yaml-rust`
//! crate: plain scalars are typed (null / bool / integer / real / string),
//! quoted scalars are always strings, and mappings keep insertion order.

use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum Yaml {
    Real(String),
    Integer(i64),
    String(String),
    Boolean(bool),
    Array(Vec<Yaml>),
    Hash(Vec<(Yaml, Yaml)>),
    Alias(String),
    Null,
    BadValue,
}

static BAD_VALUE: Yaml = Yaml::BadValue;

impl Yaml {
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Yaml::String(s) => Some(s),
            _ => None,
        }
    }

    pub fn as_hash(&self) -> Option<&Vec<(Yaml, Yaml)>> {
        match self {
            Yaml::Hash(h) => Some(h),
            _ => None,
        }
    }

    /// Look a key up in a mapping.  Anything that is not a mapping (or a
    /// missing key) yields `BadValue`, just like indexing in yaml-rust.
    pub fn get(&self, key: &str) -> &Yaml {
        if let Yaml::Hash(h) = self {
            for (k, v) in h {
                if let Yaml::String(ks) = k {
                    if ks == key {
                        return v;
                    }
                }
            }
        }
        &BAD_VALUE
    }

    /// Build a scalar from a plain (unquoted) scalar text.
    pub fn from_plain(v: &str) -> Yaml {
        if let Some(rest) = v.strip_prefix("0x") {
            if let Ok(i) = i64::from_str_radix(rest, 16) {
                return Yaml::Integer(i);
            }
        }
        if let Some(rest) = v.strip_prefix("0o") {
            if let Ok(i) = i64::from_str_radix(rest, 8) {
                return Yaml::Integer(i);
            }
        }
        if let Some(rest) = v.strip_prefix('+') {
            if let Ok(i) = rest.parse::<i64>() {
                return Yaml::Integer(i);
            }
        }
        match v {
            "~" | "null" => Yaml::Null,
            "true" => Yaml::Boolean(true),
            "false" => Yaml::Boolean(false),
            _ if v.parse::<i64>().is_ok() => Yaml::Integer(v.parse().unwrap()),
            _ if parse_real(v).is_some() => Yaml::Real(v.to_owned()),
            _ => Yaml::String(v.to_owned()),
        }
    }
}

fn parse_real(v: &str) -> Option<f64> {
    match v {
        ".inf" | ".Inf" | ".INF" | "+.inf" | "+.Inf" | "+.INF" => Some(f64::INFINITY),
        "-.inf" | "-.Inf" | "-.INF" => Some(f64::NEG_INFINITY),
        ".nan" | "NaN" | ".NAN" => Some(f64::NAN),
        _ => v.parse::<f64>().ok(),
    }
}

fn hash_insert(h: &mut Vec<(Yaml, Yaml)>, k: Yaml, v: Yaml) {
    for entry in h.iter_mut() {
        if entry.0 == k {
            entry.1 = v;
            return;
        }
    }
    h.push((k, v));
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub struct Marker {
    pub index: usize,
    pub line: usize,
    pub col: usize,
}

#[derive(Debug, Clone)]
pub struct ScanError {
    pub mark: Marker,
    pub info: String,
}

impl fmt::Display for ScanError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "ScanError {{ mark: Marker {{ index: {}, line: {}, col: {} }}, info: {:?} }}",
            self.mark.index, self.mark.line, self.mark.col, self.info
        )
    }
}

// ---------------------------------------------------------------------------
// Reader
// ---------------------------------------------------------------------------

struct Reader {
    chars: Vec<char>,
    /// byte offset of every char (plus one trailing entry for the end)
    offsets: Vec<usize>,
    pos: usize,
}

impl Reader {
    fn new(src: &str) -> Reader {
        let mut chars = Vec::new();
        let mut offsets = Vec::new();
        for (i, c) in src.char_indices() {
            chars.push(c);
            offsets.push(i);
        }
        offsets.push(src.len());
        Reader { chars, offsets, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<char> {
        self.chars.get(self.pos + off).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn at_end(&self) -> bool {
        self.pos >= self.chars.len()
    }

    fn marker_at(&self, pos: usize) -> Marker {
        let pos = pos.min(self.chars.len());
        let mut line = 1;
        let mut col = 0;
        for &c in &self.chars[..pos] {
            if c == '\n' {
                line += 1;
                col = 0;
            } else {
                col += 1;
            }
        }
        Marker { index: self.offsets[pos], line, col }
    }

    fn marker(&self) -> Marker {
        self.marker_at(self.pos)
    }

    fn error<T>(&self, pos: usize, info: &str) -> Result<T, ScanError> {
        Err(ScanError { mark: self.marker_at(pos), info: info.to_string() })
    }

    /// Column (0-based) of the current position within its line.
    fn column(&self) -> usize {
        let mut col = 0;
        let mut p = self.pos;
        while p > 0 && self.chars[p - 1] != '\n' {
            p -= 1;
            col += 1;
        }
        col
    }

    fn at_line_start(&self) -> bool {
        self.pos == 0 || self.chars[self.pos - 1] == '\n'
    }

    fn skip_spaces(&mut self) {
        while matches!(self.peek(), Some(' ') | Some('\t')) {
            self.pos += 1;
        }
    }

    /// Skip spaces and an optional comment up to (not including) the newline.
    fn skip_to_eol(&mut self) -> Result<(), ScanError> {
        self.skip_spaces();
        if let Some('#') = self.peek() {
            while let Some(c) = self.peek() {
                if c == '\n' {
                    break;
                }
                self.pos += 1;
            }
        }
        match self.peek() {
            None | Some('\n') => Ok(()),
            Some('\r') => {
                self.pos += 1;
                Ok(())
            }
            _ => self.error(self.pos, "did not find expected <document start>"),
        }
    }

    fn skip_newline(&mut self) {
        if let Some('\r') = self.peek() {
            self.pos += 1;
        }
        if let Some('\n') = self.peek() {
            self.pos += 1;
        }
    }

    /// Skip blank lines and comment lines.  Leaves the cursor at the start of
    /// the first line that has content (after its indentation is *not*
    /// consumed) or at the end of input.
    fn skip_blank_lines(&mut self) {
        loop {
            let save = self.pos;
            self.skip_spaces();
            match self.peek() {
                None => return,
                Some('\n') | Some('\r') => {
                    self.skip_newline();
                }
                Some('#') => {
                    while let Some(c) = self.peek() {
                        if c == '\n' {
                            break;
                        }
                        self.pos += 1;
                    }
                    self.skip_newline();
                }
                _ => {
                    self.pos = save;
                    return;
                }
            }
        }
    }

    /// Indentation (number of leading spaces) of the line at the cursor,
    /// assuming the cursor is at a line start.
    fn line_indent(&self) -> usize {
        let mut n = 0;
        while let Some(' ') = self.chars.get(self.pos + n) {
            n += 1;
        }
        n
    }

    fn starts_with(&self, s: &str) -> bool {
        let mut i = self.pos;
        for c in s.chars() {
            if self.chars.get(i) != Some(&c) {
                return false;
            }
            i += 1;
        }
        true
    }

    fn is_document_marker(&self) -> bool {
        if !self.at_line_start() {
            return false;
        }
        if self.starts_with("---") || self.starts_with("...") {
            matches!(self.peek_at(3), None | Some(' ') | Some('\t') | Some('\n') | Some('\r'))
        } else {
            false
        }
    }
}

fn is_blank(c: Option<char>) -> bool {
    matches!(c, None | Some(' ') | Some('\t') | Some('\n') | Some('\r'))
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

/// Parse every document in `src`.  Returns an empty vector when the input
/// contains no documents (e.g. it is empty or only has comments).
pub fn load_from_str(src: &str) -> Result<Vec<Yaml>, ScanError> {
    let mut r = Reader::new(src);
    let mut docs = Vec::new();
    loop {
        r.skip_blank_lines();
        if r.at_end() {
            break;
        }
        let mut explicit = false;
        if r.is_document_marker() {
            if r.starts_with("...") {
                r.pos += 3;
                r.skip_to_eol()?;
                r.skip_newline();
                continue;
            }
            r.pos += 3;
            explicit = true;
            r.skip_spaces();
        }
        // Content may follow `---` on the same line.
        let doc = if explicit && !matches!(r.peek(), None | Some('\n') | Some('\r') | Some('#')) {
            let node = parse_inline_or_block(&mut r, 0, true)?;
            node
        } else {
            if explicit {
                r.skip_to_eol()?;
                r.skip_newline();
            }
            r.skip_blank_lines();
            if r.at_end() || r.is_document_marker() {
                if explicit {
                    docs.push(Yaml::Null);
                }
                continue;
            }
            parse_block_node(&mut r, -1)?
        };
        docs.push(doc);
        // After a document only blank lines, comments or a marker may follow.
        r.skip_blank_lines();
        if !r.at_end() && !r.is_document_marker() {
            return r.error(r.pos, "did not find expected <document start>");
        }
    }
    Ok(docs)
}

/// Parse a node that starts on the current line (cursor is at a line start
/// or at the indentation of the line).  `parent_indent` is the indentation of
/// the enclosing collection (-1 at top level).
fn parse_block_node(r: &mut Reader, parent_indent: i64) -> Result<Yaml, ScanError> {
    r.skip_blank_lines();
    if r.at_end() || r.is_document_marker() {
        return Ok(Yaml::Null);
    }
    let indent = r.line_indent() as i64;
    if indent <= parent_indent {
        return Ok(Yaml::Null);
    }
    r.pos += indent as usize;
    let indent = indent as usize;
    if is_sequence_entry(r) {
        return parse_block_sequence(r, indent);
    }
    if line_is_mapping_entry(r) {
        return parse_block_mapping(r, indent);
    }
    // A scalar or flow collection, possibly folded over several lines.
    let node = parse_inline_or_block(r, parent_indent.max(0) as usize, false)?;
    Ok(node)
}

fn is_sequence_entry(r: &Reader) -> bool {
    r.peek() == Some('-') && is_blank(r.peek_at(1))
}

/// Determine whether the line at the cursor is `key: value` (block mapping).
fn line_is_mapping_entry(r: &Reader) -> bool {
    find_mapping_colon(r).is_some()
}

/// Find the position of the `:` that separates key and value on the current
/// line, if any.  Handles quoted keys and flow-collection keys.
fn find_mapping_colon(r: &Reader) -> Option<usize> {
    let mut i = r.pos;
    let chars = &r.chars;
    let first = *chars.get(i)?;
    if first == '"' || first == '\'' {
        // quoted key
        let q = first;
        i += 1;
        loop {
            match chars.get(i) {
                None | Some('\n') => return None,
                Some(&c) if c == q => {
                    if q == '\'' && chars.get(i + 1) == Some(&'\'') {
                        i += 2;
                        continue;
                    }
                    i += 1;
                    break;
                }
                Some('\\') if q == '"' => {
                    i += 2;
                }
                _ => i += 1,
            }
        }
        // skip spaces
        while matches!(chars.get(i), Some(' ') | Some('\t')) {
            i += 1;
        }
        if chars.get(i) == Some(&':') && is_blank(chars.get(i + 1).copied()) {
            return Some(i);
        }
        return None;
    }
    if first == '[' || first == '{' {
        // flow collection as key (rare) – find matching bracket on this line
        let mut depth = 0;
        loop {
            match chars.get(i) {
                None | Some('\n') => return None,
                Some('[') | Some('{') => depth += 1,
                Some(']') | Some('}') => {
                    depth -= 1;
                    if depth == 0 {
                        i += 1;
                        break;
                    }
                }
                _ => {}
            }
            i += 1;
        }
        while matches!(chars.get(i), Some(' ') | Some('\t')) {
            i += 1;
        }
        if chars.get(i) == Some(&':') && is_blank(chars.get(i + 1).copied()) {
            return Some(i);
        }
        return None;
    }
    if first == '#' {
        return None;
    }
    // plain key: scan until ": " or ":" at end of line; stop at " #"
    let mut prev_blank = true;
    while let Some(&c) = chars.get(i) {
        if c == '\n' || c == '\r' {
            return None;
        }
        if c == '#' && prev_blank {
            return None;
        }
        if c == ':' && is_blank(chars.get(i + 1).copied()) {
            return Some(i);
        }
        prev_blank = c == ' ' || c == '\t';
        i += 1;
    }
    None
}

fn parse_block_sequence(r: &mut Reader, indent: usize) -> Result<Yaml, ScanError> {
    let mut items = Vec::new();
    loop {
        // cursor is at the '-' of an entry
        r.pos += 1; // '-'
        r.skip_spaces();
        let item = match r.peek() {
            None | Some('\n') | Some('\r') | Some('#') => {
                r.skip_to_eol()?;
                r.skip_newline();
                parse_block_node(r, indent as i64)?
            }
            _ => {
                let col = r.column();
                if is_sequence_entry(r) {
                    // compact nested sequence: "- - a"
                    parse_block_sequence(r, col)?
                } else if line_is_mapping_entry(r) {
                    // compact mapping: "- a: 1"
                    parse_block_mapping(r, col)?
                } else {
                    parse_inline_or_block(r, indent, false)?
                }
            }
        };
        items.push(item);
        // next entry?
        r.skip_blank_lines();
        if r.at_end() || r.is_document_marker() {
            break;
        }
        let next_indent = r.line_indent();
        if next_indent < indent {
            break;
        }
        if next_indent > indent {
            let p = r.pos + next_indent;
            return r.error(p, "did not find expected '-' indicator");
        }
        r.pos += indent;
        if !is_sequence_entry(r) {
            if line_is_mapping_entry(r) {
                return r.error(r.pos, "did not find expected '-' indicator");
            }
            return r.error(r.pos, "did not find expected '-' indicator");
        }
    }
    Ok(Yaml::Array(items))
}

fn parse_block_mapping(r: &mut Reader, indent: usize) -> Result<Yaml, ScanError> {
    let mut hash: Vec<(Yaml, Yaml)> = Vec::new();
    loop {
        // cursor is at the first char of the key
        let colon = match find_mapping_colon(r) {
            Some(c) => c,
            None => return r.error(r.pos, "could not find expected ':'"),
        };
        let key = parse_key(r, colon)?;
        r.pos = colon + 1;
        r.skip_spaces();
        let value = match r.peek() {
            None | Some('\n') | Some('\r') | Some('#') => {
                r.skip_to_eol()?;
                r.skip_newline();
                // block value on following lines; a sequence may sit at the
                // same indentation as the key.
                r.skip_blank_lines();
                if !r.at_end() && !r.is_document_marker() {
                    let ni = r.line_indent();
                    if ni == indent {
                        let save = r.pos;
                        r.pos += ni;
                        if is_sequence_entry(r) {
                            parse_block_sequence(r, indent)?
                        } else {
                            r.pos = save;
                            Yaml::Null
                        }
                    } else {
                        parse_block_node(r, indent as i64)?
                    }
                } else {
                    Yaml::Null
                }
            }
            _ => parse_inline_or_block(r, indent, false)?,
        };
        hash_insert(&mut hash, key, value);
        // next entry?
        r.skip_blank_lines();
        if r.at_end() || r.is_document_marker() {
            break;
        }
        let next_indent = r.line_indent();
        if next_indent < indent {
            break;
        }
        if next_indent > indent {
            let p = r.pos + next_indent;
            // deeper indentation after a complete entry
            if let Some(c) = find_mapping_colon_at(r, p) {
                return r.error(c, "mapping values are not allowed in this context");
            }
            return r.error(p, "did not find expected key");
        }
        r.pos += indent;
        if is_sequence_entry(r) {
            return r.error(r.pos, "block sequence entries are not allowed in this context");
        }
        if !line_is_mapping_entry(r) {
            // scan the line for a ':' to give a yaml-rust-like diagnostic
            return r.error(r.pos, "could not find expected ':'");
        }
    }
    Ok(Yaml::Hash(hash))
}

fn find_mapping_colon_at(r: &Reader, pos: usize) -> Option<usize> {
    let mut tmp = Reader { chars: r.chars.clone(), offsets: r.offsets.clone(), pos };
    tmp.pos = pos;
    find_mapping_colon(&tmp)
}

fn parse_key(r: &mut Reader, colon: usize) -> Result<Yaml, ScanError> {
    let c = r.peek().unwrap_or(' ');
    if c == '"' {
        let s = parse_double_quoted(r)?;
        return Ok(Yaml::String(s));
    }
    if c == '\'' {
        let s = parse_single_quoted(r)?;
        return Ok(Yaml::String(s));
    }
    if c == '[' || c == '{' {
        let node = parse_flow_collection(r)?;
        return Ok(node);
    }
    let text: String = r.chars[r.pos..colon].iter().collect();
    let text = text.trim_end().to_string();
    r.pos = colon;
    Ok(scalar_with_props(&text))
}

/// Handle `!!str`, `&anchor`, `*alias` prefixes on a plain scalar text.
fn scalar_with_props(text: &str) -> Yaml {
    let mut t = text;
    let mut force_str = false;
    loop {
        if let Some(rest) = t.strip_prefix('&') {
            // anchor: skip the name
            let idx = rest.find(|c: char| c == ' ' || c == '\t').unwrap_or(rest.len());
            t = rest[idx..].trim_start();
            continue;
        }
        if t.starts_with('!') {
            let idx = t.find(|c: char| c == ' ' || c == '\t').unwrap_or(t.len());
            let tag = &t[..idx];
            if tag == "!!str" || tag == "!" {
                force_str = true;
            }
            t = t[idx..].trim_start();
            continue;
        }
        break;
    }
    if let Some(name) = t.strip_prefix('*') {
        return Yaml::Alias(name.to_string());
    }
    if force_str {
        return Yaml::String(t.to_string());
    }
    if t.is_empty() {
        return Yaml::Null;
    }
    Yaml::from_plain(t)
}

/// Parse a node that begins at the cursor on the current line: a quoted
/// scalar, a flow collection, a block scalar, or a plain scalar (which may be
/// folded over continuation lines indented deeper than `indent`).
fn parse_inline_or_block(r: &mut Reader, indent: usize, _top: bool) -> Result<Yaml, ScanError> {
    match r.peek() {
        Some('"') => {
            let s = parse_double_quoted(r)?;
            r.skip_to_eol()?;
            r.skip_newline();
            Ok(Yaml::String(s))
        }
        Some('\'') => {
            let s = parse_single_quoted(r)?;
            r.skip_to_eol()?;
            r.skip_newline();
            Ok(Yaml::String(s))
        }
        Some('[') | Some('{') => {
            let node = parse_flow_collection(r)?;
            r.skip_to_eol()?;
            r.skip_newline();
            Ok(node)
        }
        Some('|') | Some('>') => parse_block_scalar(r, indent),
        Some('@') | Some('`') => r.error(r.pos, "found character that cannot start any token"),
        Some('%') => r.error(r.pos, "found character that cannot start any token"),
        _ => {
            // plain scalar, possibly multi-line
            let mut text = String::new();
            let mut first = true;
            loop {
                let start = r.pos;
                let mut end = r.pos;
                let mut prev_blank = first && r.at_line_start();
                let mut i = r.pos;
                while let Some(&c) = r.chars.get(i) {
                    if c == '\n' || c == '\r' {
                        break;
                    }
                    if c == '#' && prev_blank {
                        break;
                    }
                    if c == ':' && is_blank(r.chars.get(i + 1).copied()) {
                        if !first {
                            return r.error(i, "mapping values are not allowed in this context");
                        }
                        return r.error(i, "mapping values are not allowed in this context");
                    }
                    prev_blank = c == ' ' || c == '\t';
                    i += 1;
                    if !(c == ' ' || c == '\t') {
                        end = i;
                    }
                }
                let piece: String = r.chars[start..end].iter().collect();
                if !piece.is_empty() {
                    if !text.is_empty() {
                        text.push(' ');
                    }
                    text.push_str(&piece);
                }
                r.pos = end;
                r.skip_to_eol()?;
                r.skip_newline();
                first = false;
                // continuation line?
                let save = r.pos;
                r.skip_blank_lines();
                if r.at_end() || r.is_document_marker() {
                    r.pos = save;
                    break;
                }
                let ni = r.line_indent();
                if ni <= indent {
                    r.pos = save;
                    break;
                }
                r.pos += ni;
                if is_sequence_entry(r) || line_is_mapping_entry(r) || matches!(r.peek(), Some('#')) {
                    r.pos = save;
                    break;
                }
            }
            Ok(scalar_with_props(&text))
        }
    }
}

fn parse_double_quoted(r: &mut Reader) -> Result<String, ScanError> {
    let start = r.pos;
    r.pos += 1; // opening quote
    let mut out = String::new();
    loop {
        let c = match r.bump() {
            None => return r.error(start, "while scanning a quoted scalar, found unexpected end of stream"),
            Some(c) => c,
        };
        match c {
            '"' => break,
            '\\' => {
                let e = match r.bump() {
                    None => return r.error(start, "while scanning a quoted scalar, found unexpected end of stream"),
                    Some(e) => e,
                };
                match e {
                    '0' => out.push('\0'),
                    'a' => out.push('\x07'),
                    'b' => out.push('\x08'),
                    't' | '\t' => out.push('\t'),
                    'n' => out.push('\n'),
                    'v' => out.push('\x0b'),
                    'f' => out.push('\x0c'),
                    'r' => out.push('\r'),
                    'e' => out.push('\x1b'),
                    ' ' => out.push(' '),
                    '"' => out.push('"'),
                    '/' => out.push('/'),
                    '\\' => out.push('\\'),
                    'N' => out.push('\u{85}'),
                    '_' => out.push('\u{a0}'),
                    'L' => out.push('\u{2028}'),
                    'P' => out.push('\u{2029}'),
                    'x' | 'u' | 'U' => {
                        let n = match e {
                            'x' => 2,
                            'u' => 4,
                            _ => 8,
                        };
                        let mut v: u32 = 0;
                        for _ in 0..n {
                            let h = match r.bump() {
                                Some(h) if h.is_ascii_hexdigit() => h,
                                _ => return r.error(r.pos.saturating_sub(1), "while parsing a quoted scalar, did not find expected hexdecimal number"),
                            };
                            v = v * 16 + h.to_digit(16).unwrap();
                        }
                        match char::from_u32(v) {
                            Some(ch) => out.push(ch),
                            None => return r.error(r.pos, "while parsing a quoted scalar, found invalid Unicode character escape code"),
                        }
                    }
                    '\n' => {
                        // escaped line break: skip leading whitespace on next line
                        while matches!(r.peek(), Some(' ') | Some('\t')) {
                            r.pos += 1;
                        }
                    }
                    _ => return r.error(r.pos.saturating_sub(1), "while parsing a quoted scalar, found unknown escape character"),
                }
            }
            '\n' => {
                // line folding
                while matches!(r.peek(), Some(' ') | Some('\t')) {
                    r.pos += 1;
                }
                let mut breaks = 0;
                while matches!(r.peek(), Some('\n') | Some('\r')) {
                    if r.peek() == Some('\n') {
                        breaks += 1;
                    }
                    r.pos += 1;
                    while matches!(r.peek(), Some(' ') | Some('\t')) {
                        r.pos += 1;
                    }
                }
                let trimmed_len = out.trim_end_matches([' ', '\t']).len();
                out.truncate(trimmed_len);
                if breaks == 0 {
                    out.push(' ');
                } else {
                    for _ in 0..breaks {
                        out.push('\n');
                    }
                }
            }
            '\r' => {}
            c => out.push(c),
        }
    }
    Ok(out)
}

fn parse_single_quoted(r: &mut Reader) -> Result<String, ScanError> {
    let start = r.pos;
    r.pos += 1;
    let mut out = String::new();
    loop {
        let c = match r.bump() {
            None => return r.error(start, "while scanning a quoted scalar, found unexpected end of stream"),
            Some(c) => c,
        };
        match c {
            '\'' => {
                if r.peek() == Some('\'') {
                    r.pos += 1;
                    out.push('\'');
                } else {
                    break;
                }
            }
            '\n' => {
                while matches!(r.peek(), Some(' ') | Some('\t')) {
                    r.pos += 1;
                }
                let mut breaks = 0;
                while matches!(r.peek(), Some('\n') | Some('\r')) {
                    if r.peek() == Some('\n') {
                        breaks += 1;
                    }
                    r.pos += 1;
                    while matches!(r.peek(), Some(' ') | Some('\t')) {
                        r.pos += 1;
                    }
                }
                let trimmed_len = out.trim_end_matches([' ', '\t']).len();
                out.truncate(trimmed_len);
                if breaks == 0 {
                    out.push(' ');
                } else {
                    for _ in 0..breaks {
                        out.push('\n');
                    }
                }
            }
            '\r' => {}
            c => out.push(c),
        }
    }
    Ok(out)
}

/// Parse `[...]` or `{...}` starting at the cursor (which is on the bracket).
fn parse_flow_collection(r: &mut Reader) -> Result<Yaml, ScanError> {
    let open = r.bump().unwrap();
    let start = r.pos - 1;
    let is_seq = open == '[';
    let close = if is_seq { ']' } else { '}' };
    let ctx = if is_seq { "while parsing a flow sequence" } else { "while parsing a flow mapping" };
    let mut items: Vec<Yaml> = Vec::new();
    let mut hash: Vec<(Yaml, Yaml)> = Vec::new();
    loop {
        skip_flow_ws(r);
        match r.peek() {
            None => {
                return r.error(r.pos, &format!("{}, expected ',' or '{}'", ctx, close));
            }
            Some(c) if c == close => {
                r.pos += 1;
                break;
            }
            Some(',') => {
                return r.error(r.pos, &format!("{}, did not find expected node content", ctx));
            }
            _ => {}
        }
        // parse an entry
        let key_or_item = parse_flow_node(r, is_seq)?;
        skip_flow_ws(r);
        if r.peek() == Some(':') {
            r.pos += 1;
            skip_flow_ws(r);
            let value = if matches!(r.peek(), Some(',') | Some(']') | Some('}')) {
                Yaml::Null
            } else {
                parse_flow_node(r, is_seq)?
            };
            if is_seq {
                // single-pair mapping inside a sequence
                items.push(Yaml::Hash(vec![(key_or_item, value)]));
            } else {
                hash_insert(&mut hash, key_or_item, value);
            }
        } else if is_seq {
            items.push(key_or_item);
        } else {
            hash_insert(&mut hash, key_or_item, Yaml::Null);
        }
        skip_flow_ws(r);
        match r.peek() {
            Some(',') => {
                r.pos += 1;
            }
            Some(c) if c == close => {
                r.pos += 1;
                break;
            }
            None => return r.error(r.pos, &format!("{}, expected ',' or '{}'", ctx, close)),
            _ => return r.error(r.pos, &format!("{}, expected ',' or '{}'", ctx, close)),
        }
    }
    let _ = start;
    if is_seq {
        Ok(Yaml::Array(items))
    } else {
        Ok(Yaml::Hash(hash))
    }
}

fn skip_flow_ws(r: &mut Reader) {
    loop {
        match r.peek() {
            Some(' ') | Some('\t') | Some('\n') | Some('\r') => r.pos += 1,
            Some('#') => {
                while let Some(c) = r.peek() {
                    if c == '\n' {
                        break;
                    }
                    r.pos += 1;
                }
            }
            _ => return,
        }
    }
}

fn parse_flow_node(r: &mut Reader, in_seq: bool) -> Result<Yaml, ScanError> {
    match r.peek() {
        Some('"') => Ok(Yaml::String(parse_double_quoted(r)?)),
        Some('\'') => Ok(Yaml::String(parse_single_quoted(r)?)),
        Some('[') | Some('{') => parse_flow_collection(r),
        _ => {
            let mut text = String::new();
            let mut prev_blank = false;
            while let Some(c) = r.peek() {
                if c == ',' || c == ']' || c == '}' {
                    break;
                }
                if c == ':' && (is_blank(r.peek_at(1)) || matches!(r.peek_at(1), Some(',') | Some(']') | Some('}'))) {
                    break;
                }
                if c == '#' && prev_blank {
                    break;
                }
                if c == '\n' || c == '\r' {
                    // folded
                    skip_flow_ws(r);
                    if !text.is_empty() && !text.ends_with(' ') {
                        text.push(' ');
                    }
                    prev_blank = true;
                    continue;
                }
                prev_blank = c == ' ' || c == '\t';
                text.push(c);
                r.pos += 1;
            }
            let _ = in_seq;
            let t = text.trim_end();
            if t.is_empty() {
                return Ok(Yaml::Null);
            }
            Ok(scalar_with_props(t))
        }
    }
}

fn parse_block_scalar(r: &mut Reader, indent: usize) -> Result<Yaml, ScanError> {
    let style = r.bump().unwrap(); // '|' or '>'
    let mut chomp = 0i32; // 0 clip, -1 strip, +1 keep
    let mut explicit_indent: Option<usize> = None;
    loop {
        match r.peek() {
            Some('-') => {
                chomp = -1;
                r.pos += 1;
            }
            Some('+') => {
                chomp = 1;
                r.pos += 1;
            }
            Some(d) if d.is_ascii_digit() && d != '0' => {
                explicit_indent = Some(d.to_digit(10).unwrap() as usize);
                r.pos += 1;
            }
            _ => break,
        }
    }
    r.skip_to_eol()?;
    r.skip_newline();
    // determine content indentation
    let mut lines: Vec<String> = Vec::new();
    let mut content_indent = explicit_indent.map(|n| indent + n);
    loop {
        if r.at_end() {
            break;
        }
        let li = r.line_indent();
        // blank line?
        let mut p = r.pos + li;
        let is_blank_line = matches!(r.chars.get(p), None | Some('\n') | Some('\r'));
        if is_blank_line {
            // record as empty (relative) line
            lines.push(String::new());
            while let Some(&c) = r.chars.get(p) {
                if c == '\n' {
                    break;
                }
                p += 1;
            }
            r.pos = p;
            r.skip_newline();
            continue;
        }
        if content_indent.is_none() {
            if li <= indent && !(indent == 0 && li == 0 && lines.is_empty() && false) {
                if li <= indent {
                    break;
                }
            }
            content_indent = Some(li);
        }
        let ci = content_indent.unwrap();
        if li < ci {
            break;
        }
        if r.is_document_marker() {
            break;
        }
        let start = r.pos + ci;
        let mut end = start;
        while let Some(&c) = r.chars.get(end) {
            if c == '\n' || c == '\r' {
                break;
            }
            end += 1;
        }
        let s: String = r.chars[start..end].iter().collect();
        lines.push(s);
        r.pos = end;
        r.skip_newline();
    }
    // trailing blank lines handling
    let mut trailing = 0;
    while trailing < lines.len() && lines[lines.len() - 1 - trailing].is_empty() {
        trailing += 1;
    }
    let body_len = lines.len() - trailing;
    let mut out = String::new();
    if style == '|' {
        for (i, l) in lines[..body_len].iter().enumerate() {
            out.push_str(l);
            if i + 1 < body_len {
                out.push('\n');
            }
        }
    } else {
        // folded
        let mut i = 0;
        while i < body_len {
            let l = &lines[i];
            if i > 0 {
                let prev = &lines[i - 1];
                if l.is_empty() {
                    out.push('\n');
                } else if prev.is_empty() || prev.starts_with(' ') || l.starts_with(' ') {
                    if !prev.is_empty() {
                        out.push('\n');
                    }
                } else {
                    out.push(' ');
                }
            }
            out.push_str(l);
            i += 1;
        }
    }
    if body_len > 0 {
        match chomp {
            -1 => {}
            0 => out.push('\n'),
            _ => {
                out.push('\n');
                for _ in 0..trailing {
                    out.push('\n');
                }
            }
        }
    } else if chomp == 1 {
        for _ in 0..trailing {
            out.push('\n');
        }
    }
    Ok(Yaml::String(out))
}

// ---------------------------------------------------------------------------
// Emitter
// ---------------------------------------------------------------------------

/// Serialise a document the way yaml-rust's emitter does: a `---` header,
/// two-space indentation, `{}`/`[]` for empty collections and double quotes
/// only where a plain scalar would be ambiguous.
pub fn emit(doc: &Yaml) -> String {
    let mut out = String::from("---\n");
    emit_node(&mut out, doc, 0, false);
    out
}

fn emit_node(out: &mut String, node: &Yaml, level: usize, inline: bool) {
    match node {
        Yaml::Array(v) => {
            if v.is_empty() {
                out.push_str("[]");
            } else {
                if inline {
                    out.push('\n');
                }
                for (i, item) in v.iter().enumerate() {
                    if i > 0 || inline {
                        push_indent(out, level);
                    }
                    out.push('-');
                    emit_value(out, item, level);
                    if i + 1 < v.len() {
                        out.push('\n');
                    }
                }
            }
        }
        Yaml::Hash(h) => {
            if h.is_empty() {
                out.push_str("{}");
            } else {
                if inline {
                    out.push('\n');
                }
                for (i, (k, v)) in h.iter().enumerate() {
                    if i > 0 || inline {
                        push_indent(out, level);
                    }
                    emit_scalar(out, k);
                    out.push(':');
                    emit_value(out, v, level);
                    if i + 1 < h.len() {
                        out.push('\n');
                    }
                }
            }
        }
        _ => emit_scalar(out, node),
    }
}

fn emit_value(out: &mut String, v: &Yaml, level: usize) {
    match v {
        Yaml::Array(a) if !a.is_empty() => emit_node(out, v, level + 1, true),
        Yaml::Hash(h) if !h.is_empty() => emit_node(out, v, level + 1, true),
        _ => {
            out.push(' ');
            emit_node(out, v, level + 1, false);
        }
    }
}

fn push_indent(out: &mut String, level: usize) {
    for _ in 0..level {
        out.push_str("  ");
    }
}

fn emit_scalar(out: &mut String, node: &Yaml) {
    match node {
        Yaml::String(s) => {
            if need_quotes(s) {
                escape_str(out, s);
            } else {
                out.push_str(s);
            }
        }
        Yaml::Boolean(b) => out.push_str(if *b { "true" } else { "false" }),
        Yaml::Integer(i) => out.push_str(&i.to_string()),
        Yaml::Real(r) => out.push_str(r),
        Yaml::Null | Yaml::BadValue => out.push('~'),
        Yaml::Alias(a) => {
            out.push('*');
            out.push_str(a);
        }
        Yaml::Array(_) | Yaml::Hash(_) => emit_node(out, node, 0, false),
    }
}

fn need_quotes(s: &str) -> bool {
    fn need_quotes_spaces(s: &str) -> bool {
        s.starts_with(' ') || s.ends_with(' ')
    }
    s.is_empty()
        || need_quotes_spaces(s)
        || s.starts_with(|c: char| matches!(c, '&' | '*' | '?' | '|' | '-' | '<' | '>' | '=' | '!' | '%' | '@'))
        || s.contains(|c: char| {
            matches!(c,
                ':' | '{' | '}' | '[' | ']' | ',' | '#' | '`' | '"' | '\'' | '\\'
                | '\0'..='\x06' | '\t' | '\n' | '\r' | '\x0e'..='\x1a' | '\x1c'..='\x1f')
        })
        || [
            "yes", "Yes", "YES", "no", "No", "NO", "True", "TRUE", "true", "False", "FALSE", "false",
            "on", "On", "ON", "off", "Off", "OFF", "null", "Null", "NULL", "~",
        ]
        .contains(&s)
        || s.starts_with('.')
        || s.starts_with("0x")
        || s.parse::<i64>().is_ok()
        || s.parse::<f64>().is_ok()
}

fn escape_str(out: &mut String, v: &str) {
    out.push('"');
    for c in v.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\x08' => out.push_str("\\b"),
            '\x0c' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 || c as u32 == 0x7f => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
}
