/// Parse a hex colour string such as `#1a2b3c` into RGB components.
///
/// The string is upper-cased first; one leading `#` is optional and any
/// characters after the first six hex digits are ignored.  Invalid input is
/// a hard failure, mirroring the behaviour of the colour naming library the
/// original tool relies on.
pub fn parse_hex(input: &str) -> (String, [u8; 3]) {
    let upper = input.to_uppercase();
    let body = upper.strip_prefix('#').unwrap_or(&upper);
    let chars: Vec<char> = body.chars().collect();
    if chars.len() < 6 {
        fail_at(COLOR_RS, 46, 9, format!("got invalid hex string: {:?}", upper));
    }
    let mut rgb = [0u8; 3];
    for i in 0..3 {
        let pair: String = chars[i * 2..i * 2 + 2].iter().collect();
        match u8::from_str_radix(&pair, 16) {
            Ok(v) => rgb[i] = v,
            Err(_) => fail_at(COLOR_RS, 53, 13, format!("got invalid hex string: {:?}", upper)),
        }
    }
    (upper, rgb)
}

fn sq(a: u8, b: u8) -> i64 {
    let d = a as i64 - b as i64;
    d * d
}

/// Return the name of the named colour closest (in RGB space) to `rgb`.
pub fn nearest_name(rgb: [u8; 3]) -> &'static str {
    let mut best: Option<(i64, &'static str)> = None;
    for (name, c) in NAMED_COLORS {
        let d = sq(rgb[0], c[0]) + sq(rgb[1], c[1]) + sq(rgb[2], c[2]);
        match best {
            Some((bd, _)) if bd < d => {}
            Some((bd, bn)) if bd == d => {
                best = Some((d, break_tie(rgb, bn, name)));
            }
            _ => best = Some((d, name)),
        }
    }
    best.map(|b| b.1).unwrap_or("black")
}

/// Decide between two equally distant names.
fn break_tie(rgb: [u8; 3], first: &'static str, second: &'static str) -> &'static str {
    let (r, g, b) = (rgb[0] as f64, rgb[1] as f64, rgb[2] as f64);
    match (first, second) {
        ("gray", "grey") | ("grey", "gray") => {
            if r + g + b <= 384.0 {
                "grey"
            } else {
                "gray"
            }
        }
        ("lightslategray", "lightslategrey") | ("lightslategrey", "lightslategray") => {
            let (or, og, ob) = (r - 119.0, g - 136.0, b - 153.0);
            if 0.25 * or + 0.89 * og - ob >= -0.22 {
                "lightslategrey"
            } else {
                "lightslategray"
            }
        }
        _ => second,
    }
}

/// Assigns unique names to colours, remembering previously named colours so
/// that the same hex string always maps to the same name.
pub struct Namer {
    pub entries: Vec<(String, String)>, // (name, hex)
}

impl Namer {
    pub fn new() -> Namer {
        Namer { entries: Vec::new() }
    }

    pub fn name(&mut self, hex: &str) -> String {
        let (upper, rgb) = parse_hex(hex);
        for (n, h) in &self.entries {
            if *h == upper {
                return n.clone();
            }
        }
        let base = nearest_name(rgb);
        let mut candidate = base.to_string();
        let mut i = 1;
        while self.entries.iter().any(|(n, _)| *n == candidate) {
            candidate = format!("{}-{}", base, i);
            i += 1;
        }
        self.entries.push((candidate.clone(), upper));
        candidate
    }
}
