//! Theme representation, theme-file loading and the reverse operation of
//! deriving a theme from an existing i3 configuration.

use std::fs;

use crate::namer::Namer;
use crate::yaml::{self, Yaml};

/// Colours of one window decoration class (`client.focused`, ...).
#[derive(Debug, Clone)]
pub struct WindowColor {
    pub border: String,
    pub background: String,
    pub text: String,
    pub indicator: Option<String>,
}

/// Colours of one workspace button class in the bar.
#[derive(Debug, Clone)]
pub struct WorkspaceColor {
    pub border: String,
    pub background: String,
    pub text: String,
    pub indicator: Option<String>,
}

#[derive(Debug, Clone, Default)]
pub struct WindowColors {
    pub focused: Option<WindowColor>,
    pub focused_inactive: Option<WindowColor>,
    pub unfocused: Option<WindowColor>,
    pub urgent: Option<WindowColor>,
}

#[derive(Debug, Clone, Default)]
pub struct BarColors {
    pub separator: Option<String>,
    pub background: Option<String>,
    pub statusline: Option<String>,
    pub focused_workspace: Option<WorkspaceColor>,
    pub active_workspace: Option<WorkspaceColor>,
    pub inactive_workspace: Option<WorkspaceColor>,
    pub urgent_workspace: Option<WorkspaceColor>,
}

#[derive(Debug, Clone, Default)]
pub struct Theme {
    pub description: Option<String>,
    pub window_colors: Option<WindowColors>,
    pub bar_colors: Option<BarColors>,
}

pub const WINDOW_CLASSES: [&str; 4] = ["focused", "focused_inactive", "unfocused", "urgent"];
pub const WORKSPACE_CLASSES: [&str; 4] =
    ["focused_workspace", "active_workspace", "inactive_workspace", "urgent_workspace"];

impl WindowColors {
    pub fn get(&self, class: &str) -> Option<&WindowColor> {
        match class {
            "focused" => self.focused.as_ref(),
            "focused_inactive" => self.focused_inactive.as_ref(),
            "unfocused" => self.unfocused.as_ref(),
            "urgent" => self.urgent.as_ref(),
            _ => None,
        }
    }
}

impl BarColors {
    pub fn single(&self, key: &str) -> Option<&String> {
        match key {
            "separator" => self.separator.as_ref(),
            "background" => self.background.as_ref(),
            "statusline" => self.statusline.as_ref(),
            _ => None,
        }
    }

    pub fn workspace(&self, class: &str) -> Option<&WorkspaceColor> {
        match class {
            "focused_workspace" => self.focused_workspace.as_ref(),
            "active_workspace" => self.active_workspace.as_ref(),
            "inactive_workspace" => self.inactive_workspace.as_ref(),
            "urgent_workspace" => self.urgent_workspace.as_ref(),
            _ => None,
        }
    }
}

// ---------------------------------------------------------------------------
// Loading a theme from YAML
// ---------------------------------------------------------------------------

struct Palette<'a> {
    colors: Option<&'a Vec<(Yaml, Yaml)>>,
}

impl<'a> Palette<'a> {
    /// Resolve a colour value: named colours are looked up in the palette,
    /// anything else is used verbatim.  Non-string values are ignored.
    fn resolve(&self, value: &Yaml) -> Option<String> {
        let s = value.as_str()?;
        if let Some(colors) = self.colors {
            for (k, v) in colors {
                if k.as_str() == Some(s) {
                    if let Some(hex) = v.as_str() {
                        return Some(hex.to_string());
                    }
                }
            }
        }
        Some(s.to_string())
    }

    fn resolve_or_black(&self, value: &Yaml) -> String {
        self.resolve(value).unwrap_or_else(|| "#000000".to_string())
    }

    fn window(&self, node: &Yaml) -> Option<WindowColor> {
        node.as_hash()?;
        Some(WindowColor {
            border: self.resolve_or_black(node.get("border")),
            background: self.resolve_or_black(node.get("background")),
            text: self.resolve_or_black(node.get("text")),
            indicator: self.resolve(node.get("indicator")),
        })
    }

    fn workspace(&self, node: &Yaml) -> Option<WorkspaceColor> {
        node.as_hash()?;
        Some(WorkspaceColor {
            border: self.resolve(node.get("border"))?,
            background: self.resolve(node.get("background"))?,
            text: self.resolve(node.get("text"))?,
            indicator: self.resolve(node.get("indicator")),
        })
    }
}

impl Theme {
    pub fn from_yaml(doc: &Yaml) -> Theme {
        let palette = Palette { colors: doc.get("colors").as_hash() };
        let description = doc.get("meta").get("description").as_str().map(|s| s.to_string());

        let wc = doc.get("window_colors");
        let window_colors = wc.as_hash().map(|_| WindowColors {
            focused: palette.window(wc.get("focused")),
            focused_inactive: palette.window(wc.get("focused_inactive")),
            unfocused: palette.window(wc.get("unfocused")),
            urgent: palette.window(wc.get("urgent")),
        });

        let bc = doc.get("bar_colors");
        let bar_colors = bc.as_hash().map(|_| BarColors {
            separator: palette.resolve(bc.get("separator")),
            background: palette.resolve(bc.get("background")),
            statusline: palette.resolve(bc.get("statusline")),
            focused_workspace: palette.workspace(bc.get("focused_workspace")),
            active_workspace: palette.workspace(bc.get("active_workspace")),
            inactive_workspace: palette.workspace(bc.get("inactive_workspace")),
            urgent_workspace: palette.workspace(bc.get("urgent_workspace")),
        });

        Theme { description, window_colors, bar_colors }
    }
}

