// ---------------------------------------------------------------------------
// Deriving a theme from a config file
// ---------------------------------------------------------------------------

/// Raw colour strings collected from a configuration file.
#[derive(Default, Debug)]
pub struct ConfigColors {
    pub separator: Option<String>,
    pub background: Option<String>,
    pub statusline: Option<String>,
    pub focused_workspace: Option<(String, String, Option<String>)>,
    pub inactive_workspace: Option<(String, String, Option<String>)>,
    pub urgent_workspace: Option<(String, String, Option<String>)>,
    pub focused: Option<(String, String, String, Option<String>)>,
    pub focused_inactive: Option<(String, String, String, Option<String>)>,
    pub unfocused: Option<(String, String, String, Option<String>)>,
    pub urgent: Option<(String, String, String, Option<String>)>,
}

/// Split a config line into its space separated words (tabs are not
/// separators, matching the behaviour of the original tool).
pub fn words(line: &str) -> Vec<&str> {
    line.trim().split(' ').filter(|w| !w.is_empty()).collect()
}

pub fn parse_config(text: &str) -> ConfigColors {
    let mut cc = ConfigColors::default();
    let mut in_bar = false;
    let mut in_colors = false;
    for line in text.lines() {
        let tokens = words(line);
        let first = match tokens.first() {
            Some(f) => *f,
            None => continue,
        };
        if in_colors {
            match first {
                "}" => in_colors = false,
                "separator" => {
                    cc.separator = Some(tokens[1].to_string());
                }
                "background" => {
                    cc.background = Some(tokens[1].to_string());
                }
                "statusline" => {
                    cc.statusline = Some(tokens[1].to_string());
                }
                "focused_workspace" => {
                    let border = tokens[1].to_string();
                    let background = tokens[2].to_string();
                    let text = tokens.get(3).map(|s| s.to_string());
                    cc.focused_workspace = Some((border, background, text));
                }
                "inactive_workspace" => {
                    let border = tokens[1].to_string();
                    let background = tokens[2].to_string();
                    let text = tokens.get(3).map(|s| s.to_string());
                    cc.inactive_workspace = Some((border, background, text));
                }
                "urgent_workspace" => {
                    let border = tokens[1].to_string();
                    let background = tokens[2].to_string();
                    let text = tokens.get(3).map(|s| s.to_string());
                    cc.urgent_workspace = Some((border, background, text));
                }
                _ => {}
            }
        } else if in_bar {
            match first {
                "colors" => in_colors = true,
                "}" => in_bar = false,
                _ => {}
            }
        } else if first == "bar" {
            in_bar = true;
        } else if let Some(class) = first.strip_prefix("client.") {
            if WINDOW_CLASSES.contains(&class) {
                let border = tokens[1].to_string();
                let background = tokens[2].to_string();
                let text = tokens[3].to_string();
                let indicator = tokens.get(4).map(|s| s.to_string());
                let value = Some((border, background, text, indicator));
                match class {
                    "focused" => cc.focused = value,
                    "focused_inactive" => cc.focused_inactive = value,
                    "unfocused" => cc.unfocused = value,
                    _ => cc.urgent = value,
                }
            }
        }
    }
    cc
}

/// Build the YAML document describing the colours found in a config.
pub fn config_to_theme_yaml(cc: &ConfigColors) -> Yaml {
    let mut namer = Namer::new();
    let s = |v: &str| Yaml::String(v.to_string());

    // Name every colour first, in a fixed order, so that the names are
    // stable regardless of where they are used.
    let separator = cc.separator.as_ref().map(|c| namer.name(c));
    let background = cc.background.as_ref().map(|c| namer.name(c));
    let statusline = cc.statusline.as_ref().map(|c| namer.name(c));
    let mut name_ws = |ws: &Option<(String, String, Option<String>)>| {
        ws.as_ref().map(|(b, bg, t)| {
            (namer.name(b), namer.name(bg), t.as_ref().map(|t| namer.name(t)))
        })
    };
    let focused_workspace = name_ws(&cc.focused_workspace);
    let _inactive_workspace = name_ws(&cc.inactive_workspace);
    let urgent_workspace = name_ws(&cc.urgent_workspace);
    let mut name_win = |w: &Option<(String, String, String, Option<String>)>| {
        w.as_ref().map(|(b, bg, t, i)| {
            (namer.name(b), namer.name(bg), namer.name(t), i.as_ref().map(|i| namer.name(i)))
        })
    };
    let focused = name_win(&cc.focused);
    let focused_inactive = name_win(&cc.focused_inactive);
    let unfocused = name_win(&cc.unfocused);
    let urgent = name_win(&cc.urgent);

    let mut meta = Vec::new();
    meta.push((s("description"), s("AUTOMATICALLY GENERATED THEME")));

    let colors: Vec<(Yaml, Yaml)> =
        namer.entries.iter().map(|(n, h)| (s(n), s(h))).collect();

    let mut window_colors = Vec::new();
    for (class, value) in [
        ("focused", &focused),
        ("focused_inactive", &focused_inactive),
        ("unfocused", &unfocused),
        ("urgent", &urgent),
    ] {
        if let Some((b, bg, t, i)) = value {
            let mut h = vec![(s("border"), s(b)), (s("background"), s(bg)), (s("text"), s(t))];
            if let Some(i) = i {
                h.push((s("indicator"), s(i)));
            }
            window_colors.push((s(class), Yaml::Hash(h)));
        }
    }

    let mut bar_colors = Vec::new();
    if let Some(c) = &background {
        bar_colors.push((s("background"), s(c)));
    }
    if let Some(c) = &statusline {
        bar_colors.push((s("statusline"), s(c)));
    }
    if let Some(c) = &separator {
        bar_colors.push((s("separator"), s(c)));
    }
    for (class, value) in [("focused_workspace", &focused_workspace), ("urgent_workspace", &urgent_workspace)] {
        if let Some((b, bg, t)) = value {
            let mut h = vec![(s("border"), s(b)), (s("background"), s(bg))];
            if let Some(t) = t {
                h.push((s("text"), s(t)));
            }
            bar_colors.push((s(class), Yaml::Hash(h)));
        }
    }

    Yaml::Hash(vec![
        (s("meta"), Yaml::Hash(meta)),
        (s("colors"), Yaml::Hash(colors)),
        (s("window_colors"), Yaml::Hash(window_colors)),
        (s("bar_colors"), Yaml::Hash(bar_colors)),
    ])
}

/// Read a config file and print the theme it describes.
pub fn print_theme_for_config(path: &str) {
    let text = fs::read_to_string(path).unwrap();
    let cc = parse_config(&text);
    let doc = config_to_theme_yaml(&cc);
    println!("{}", yaml::emit(&doc));
}
