                    if let Some(e) = extra {
                        out.push(' ');
                        out.push_str(&e);
                    }
                    self.emit_line(&out);
                }
                None => self.emit_line(line),
            }
            return;
        }
        // Anything else inside the colors block is dropped.
    }

    fn handle_client_line(&mut self, line: &str, class: &str) {
        self.clients_seen.push(class.to_string());
        let themed = self.theme.window_colors.as_ref().and_then(|w| w.get(class).cloned());
        match themed {
            Some(wc) => {
                let indent = indent_of(line);
                let mut out = format!("{}client.{} {} {} {}", indent, class, wc.border, wc.background, wc.text);
                if let Some(i) = &wc.indicator {
                    out.push(' ');
                    out.push_str(i);
                }
                self.emit_line(&out);
            }
            None => self.emit_line(line),
        }
    }

    pub fn apply(&mut self, config: &str) {
        for line in config.lines() {
            let tokens = words(line);
            let first = tokens.first().copied();
            if self.in_colors {
                match first {
                    None => self.emit_line(line),
                    Some(_) => self.handle_colors_line(line, &tokens),
                }
                continue;
            }
            if self.in_bar {
                match first {
                    Some("colors") => {
                        self.in_colors = true;
                        self.colors_seen.clear();
                        self.emit_line(line);
                    }
                    Some("}") => {
                        if !self.bar_has_colors {
                            self.new_colors_block();
                        }
                        self.in_bar = false;
                        self.bar_has_colors = false;
                        self.emit_line(line);
                    }
                    Some(f) if f.starts_with("client.") && WINDOW_CLASSES.contains(&&f[7..]) => {
                        self.handle_client_line(line, &f[7..]);
                    }
                    _ => self.emit_line(line),
                }
                continue;
            }
            match first {
                Some("bar") => {
                    self.in_bar = true;
                    self.emit_line(line);
                }
                Some(f) if f.starts_with("client.") && WINDOW_CLASSES.contains(&&f[7..]) => {
                    self.handle_client_line(line, &f[7..]);
                }
                _ => self.emit_line(line),
            }
        }
        self.append_clients();
    }

    /// Add `client.*` lines for the window classes the config did not have.
    fn append_clients(&mut self) {
        let missing: Vec<&str> = WINDOW_CLASSES
            .iter()
            .copied()
            .filter(|c| !self.clients_seen.iter().any(|s| s == c))
            .collect();
        for class in missing {
            let wc = self.theme.window_colors.as_ref().unwrap().get(class).cloned();
            if let Some(wc) = wc {
                let mut out = format!("client.{} {} {} {}", class, wc.border, wc.background, wc.text);
                if let Some(i) = &wc.indicator {
                    out.push(' ');
                    out.push_str(i);
                }
                self.emit_line(&out);
            }
        }
    }
}

pub fn apply_theme(theme: &Theme, config: &str, out: &mut dyn Write) {
    let mut applier = Applier::new(theme, out);
    applier.apply(config);
}
EOF
echo ok

