    pub theme: Option<String>,
    pub config: Option<String>,
    pub output: Option<String>,
    pub to_theme: Option<String>,
    pub to_theme_given: bool,
    pub list_all: bool,
    pub reload: bool,
    pub save: bool,
}

/// How the process should terminate when parsing does not yield matches.
pub struct Exit {
    pub stdout: bool,
    pub message: String,
    pub code: i32,
}

struct Colorizer {
    on: bool,
}

impl Colorizer {
    fn error(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

struct Parser {
    bin: String,
    /// names of flags/options seen so far, in order of first appearance
    used: Vec<String>,
    occurrences: Vec<(String, usize)>,
    matches: Matches,
    color: Colorizer,
}

impl Parser {
    fn record(&mut self, name: &str) {
        if !self.used.iter().any(|u| u == name) {
            self.used.push(name.to_string());
        }
        if let Some(e) = self.occurrences.iter_mut().find(|(n, _)| n == name) {
            e.1 += 1;
        } else {
            self.occurrences.push((name.to_string(), 1));
        }
    }

    fn usage_line(&self, extra: Option<&str>) -> String {
        let mut used: Vec<String> = self.used.clone();
        if let Some(e) = extra {
            if !used.iter().any(|u| u == e) {
                used.push(e.to_string());
            }
        }
        if used.is_empty() {
            return format!("{} [FLAGS] [OPTIONS] [theme]", self.bin);
        }
        used.sort();
        let parts: Vec<String> = used.iter().map(|n| display(def(n))).collect();
        format!("{} {}", self.bin, parts.join(" "))
    }

    fn usage_block(&self, extra: Option<&str>) -> String {
        format!("USAGE:\n    {}", self.usage_line(extra))
    }

    fn error_exit(&self, body: String, extra: Option<&str>) -> Exit {
        let message = format!(
            "{} {}\n\n{}\n\nFor more information try {}\n",
            self.color.error("error:"),
            body,
            self.usage_block(extra),
            self.color.good("--help")
        );
        Exit { stdout: false, message, code: 1 }
    }

    fn unknown_argument(&self, arg: &str, suffix: &str, extra: Option<&str>) -> Exit {
        let body = format!(
            "Found argument '{}' which wasn't expected, or isn't valid in this context{}",
            self.color.warning(arg),
            suffix
        );
        self.error_exit(body, extra)
    }

    fn empty_value(&self, name: &str) -> Exit {
        let body = format!(
            "The argument '{}' requires a value but none was supplied",
            self.color.warning(&display(def(name)))
        );
        self.error_exit(body, None)
    }

    fn multiple_usage(&self, name: &str) -> Exit {
        let body = format!(
            "The argument '{}' was provided more than once, but cannot be used multiple times",
            self.color.warning(&display(def(name)))
        );
        self.error_exit(body, None)
    }

    fn set_flag(&mut self, name: &str) -> Result<(), Exit> {
        match name {
            "help" => {
                return Err(Exit { stdout: true, message: help_text(&self.bin), code: 0 });
            }
            "version" => {
                return Err(Exit { stdout: true, message: format!("{} {}\n", NAME, VERSION), code: 0 });
            }
            "list-all" => self.matches.list_all = true,
            "reload" => self.matches.reload = true,
            "save" => self.matches.save = true,
            _ => {}
        }
        self.record(name);
        Ok(())
    }

    fn set_value(&mut self, name: &str, value: &str) {
        match name {
            "config" => self.matches.config = Some(value.to_string()),
            "output" => self.matches.output = Some(value.to_string()),
            "to-theme" => {
                self.matches.to_theme = Some(value.to_string());
                self.matches.to_theme_given = true;
            }
            _ => {}
        }
    }

    fn has_value(&self, name: &str) -> bool {
        match name {
            "config" => self.matches.config.is_some(),
            "output" => self.matches.output.is_some(),
            "to-theme" => self.matches.to_theme.is_some(),
            _ => true,
        }
    }
}

/// Suggest a long option for a mistyped one (Jaro-Winkler similarity).
fn did_you_mean(input: &str) -> Option<&'static str> {
    let mut best: Option<(f64, &'static str)> = None;
    for a in ARGS {
        let score = jaro_winkler(input, a.long);
        if score > 0.8 && best.map_or(true, |(b, _)| b < score) {
            best = Some((score, a.long));
        }
    }
    best.map(|b| b.1)
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (al, bl) = (a.len(), b.len());
    if al == 0 && bl == 0 {
        return 1.0;
    } else if al == 0 || bl == 0 {
        return 0.0;
    } else if al == 1 && bl == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let search_range = (al.max(bl) / 2) - 1;
    let mut consumed = vec![false; bl];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0usize;
    for (i, &ac) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (bl - 1).min(i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, &bc) in b.iter().enumerate() {
            if min_bound <= j && j <= max_bound && ac == bc && !consumed[j] {
                consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / al as f64) + (matches / bl as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jd = jaro(a, b);
    let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let jw = jd + (0.1 * prefix as f64 * (1.0 - jd));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

pub fn help_text(bin: &str) -> String {
    let mut s = String::new();
    s.push_str(&format!("{} {}\n{}\n\n", NAME, VERSION, ABOUT));
    s.push_str(&format!("USAGE:\n    {} [FLAGS] [OPTIONS] [theme]\n\n", bin));
    let flags: Vec<&ArgDef> = ARGS.iter().filter(|a| a.kind == Kind::Flag).collect();
    let opts: Vec<&ArgDef> = ARGS.iter().filter(|a| a.kind == Kind::Opt).collect();
    let flag_w = flags.iter().map(|a| a.long.len()).max().unwrap_or(0);
    s.push_str("FLAGS:\n");
    for a in &flags {
        s.push_str(&format!("    -{}, --{:<w$}    {}\n", a.short, a.long, a.help, w = flag_w));
    }
    s.push('\n');
    let opt_w = opts.iter().map(|a| a.long.len() + 3 + a.value_name.len()).max().unwrap_or(0);
    s.push_str("OPTIONS:\n");
    for a in &opts {
        let spec = format!("--{} <{}>", a.long, a.value_name);
        let col = 4 + 4 + opt_w + 4;
        let mut help = a.help.to_string();
        if let Some(d) = a.default {
            let spec_vals = format!(" [default: {}]", d);
            let avail = 120 - col;
            if help.len() + spec_vals.len() > avail {
                help.push('\n');
                help.push_str(&" ".repeat(col));
                help.push_str(spec_vals.trim_start());
            } else {
                help.push_str(&spec_vals);
            }
        }
        s.push_str(&format!("    -{}, {:<w$}    {}\n", a.short, spec, help, w = opt_w));
    }
    s.push('\n');
    s.push_str("ARGS:\n    <theme>    The theme to use\n");
    s
}

pub fn parse(argv: &[String]) -> Result<Matches, Exit> {
    let bin = argv
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "i3-style".to_string());
    let mut p = Parser {
        bin,
        used: Vec::new(),
        occurrences: Vec::new(),
        matches: Matches::default(),
        color: Colorizer { on: std::io::stderr().is_terminal() },
    };
    let mut pending: Option<&'static str> = None;
    let mut pos_only = false;

    for arg in argv.iter().skip(1) {
        let starts_new = if pos_only {
            false
        } else if arg.starts_with("--") {
            true
        } else if arg.starts_with('-') {
            arg.len() != 1
        } else {
            false
        };

        if let Some(name) = pending {
            if !starts_new {
                p.set_value(name, arg);
                pending = None;
                continue;
            }
            // leave the option without a value; handled at the end
            pending = None;
        }

        if pos_only {
            if p.matches.theme.is_none() {
                p.matches.theme = Some(arg.clone());
            } else {
                return Err(p.unknown_argument(arg, "", None));
            }
            continue;
        }

        if arg.starts_with("--") {
            if arg.len() == 2 {
                pos_only = true;
                continue;
            }
            let body = arg.trim_start_matches('-');
            let (name, value) = match body.find('=') {
                Some(i) => (&body[..i], Some(&body[i + 1..])),
                None => (body, None),
            };
            if let Some(a) = ARGS.iter().find(|a| a.long == name) {
                match a.kind {
                    Kind::Flag => p.set_flag(a.name)?,
                    Kind::Opt => {
                        p.record(a.name);
                        match value {
                            Some(v) => p.set_value(a.name, v),
                            None => pending = Some(a.name),
                        }
                    }
                }
            } else {
                let (suffix, extra) = match did_you_mean(name) {
                    Some(cand) => {
                        let c = Colorizer { on: true };
                        (format!("\n\tDid you mean {}{}?", c.good("--"), c.good(cand)), Some(def_by_long(cand)))
                    }
                    None => (String::new(), None),
                };
                return Err(p.unknown_argument(&format!("--{}", name), &suffix, extra));
            }
            continue;
        }

        if arg.starts_with('-') && arg.len() > 1 {
            let chars: Vec<char> = arg.chars().skip(1).collect();
            let mut i = 0;
            while i < chars.len() {
                let c = chars[i];
                match ARGS.iter().find(|a| a.short == c) {
                    Some(a) if a.kind == Kind::Flag => {
                        p.set_flag(a.name)?;
                        i += 1;
                    }
                    Some(a) => {
                        p.record(a.name);
                        let rest: String = chars[i + 1..].iter().collect();
                        if rest.is_empty() {
                            pending = Some(a.name);
                        } else {
                            let v = rest.strip_prefix('=').unwrap_or(&rest);
                            p.set_value(a.name, v);
                        }
                        break;
                    }
                    None => {
                        return Err(p.unknown_argument(&format!("-{}", c), "", None));
                    }
                }
            }
            continue;
        }

        // positional
        if p.matches.theme.is_none() {
            p.matches.theme = Some(arg.clone());
        } else {
            return Err(p.unknown_argument(arg, "", None));
        }
    }

    // defaults
    if !p.matches.to_theme_given {
        p.matches.to_theme = Some(String::new());
        p.record("to-theme");
    }

    if let Some(name) = pending {
        if !p.has_value(name) {
            return Err(p.empty_value(name));
        }
    }

    let occurrences = p.occurrences.clone();
    for (name, count) in &occurrences {
        if def(name).kind == Kind::Opt && !p.has_value(name) {
            return Err(p.empty_value(name));
        }
        if *count > 1 {
            return Err(p.multiple_usage(name));
        }
    }

    Ok(p.matches)
}

fn def_by_long(long: &str) -> &'static str {
    ARGS.iter().find(|a| a.long == long).map(|a| a.name).unwrap_or(long)
}
EOF
echo ok"}

