cat > src/writer.rs <<'EOF'
//! Applies a theme to an i3 configuration, rewriting the colour directives
//! while leaving everything else untouched.

use std::fs;
use std::io::{Read, Write};

use crate::theme::{words, Theme, WINDOW_CLASSES, WORKSPACE_CLASSES};

const SINGLE_KEYS: [&str; 3] = ["separator", "background", "statusline"];
const BLACK: &str = "#000000";

/// Destination of the rewritten configuration.
pub enum Sink<'a> {
    Stdout,
    File(&'a mut fs::File),
}

impl<'a> Sink<'a> {
    fn write_str(&mut self, s: &str) {
        match self {
            Sink::Stdout => print!("{}", s),
            Sink::File(f) => f.write_all(s.as_bytes()).unwrap(),
        }
    }
}

pub fn read_config(path: &str) -> String {
    let mut file = fs::File::open(path).unwrap();
    let mut contents = String::new();
    file.read_to_string(&mut contents).unwrap();
    contents
}

/// Leading whitespace of a line.
fn indent_of(line: &str) -> &str {
    let trimmed = line.trim_start();
    &line[..line.len() - trimmed.len()]
}

/// Writer state while walking through the configuration line by line.
pub struct Applier<'a> {
    theme: &'a Theme,
    out: &'a mut Sink<'a>,
    in_bar: bool,
    in_colors: bool,
    bar_has_colors: bool,
    colors_seen: Vec<String>,
    clients_seen: Vec<String>,
}

impl<'a> Applier<'a> {
    pub fn new(theme: &'a Theme, out: &'a mut Sink<'a>) -> Applier<'a> {
        Applier {
            theme,
            out,
            in_bar: false,
            in_colors: false,
            bar_has_colors: false,
            colors_seen: Vec::new(),
            clients_seen: Vec::new(),
        }
    }

    fn emit(&mut self, s: &str) {
        self.out.write_str(s);
    }

    fn emit_line(&mut self, s: &str) {
        self.out.write_str(s);
        self.out.write_str("\n");
    }

    /// Lines of a complete `colors` block for the theme (without the
    /// surrounding braces), skipping entries the block already had.
    fn missing_color_lines(&self, skip: &[String]) -> Vec<String> {
        let bar = self.theme.bar_colors.as_ref().unwrap();
        let mut lines = Vec::new();
        for key in SINGLE_KEYS {
            if skip.iter().any(|k| k == key) {
                continue;
            }
            if let Some(c) = bar.single(key) {
                lines.push(format!("{} {}", key, c));
            }
        }
        for class in WORKSPACE_CLASSES {
            if skip.iter().any(|k| k == class) {
                continue;
            }
            if let Some(ws) = bar.workspace(class) {
                if let (Some(b), Some(bg), Some(t)) = (&ws.border, &ws.background, &ws.text) {
                    let extra = match &ws.indicator {
                        Some(i) => format!(" {}", i),
                        None => String::new(),
                    };
                    lines.push(format!("{} {} {} {} {}", class, b, bg, t, extra));
                }
            }
        }
        lines
    }

    /// Append the colour entries the existing `colors` block did not have.
    fn finish_colors_block(&mut self, indent: &str) {
        let pad = format!("{}{}", indent, indent);
        let seen = self.colors_seen.clone();
        for line in self.missing_color_lines(&seen) {
            self.emit_line(&format!("{}{}", pad, line));
        }
    }

    /// Emit a fresh `colors` block for a bar that had none.
    fn new_colors_block(&mut self) {
        self.emit_line("  colors {");
        for line in self.missing_color_lines(&[]) {
            self.emit_line(&format!("    {}", line));
        }
        self.emit_line("  }");
    }

    fn handle_colors_line(&mut self, line: &str, tokens: &[&str]) {
        let first = tokens[0];
        let indent = indent_of(line);
        if first.starts_with('#') {
            self.emit_line(line);
            return;
        }
        if first == "}" {
            self.finish_colors_block(indent);
            self.emit_line(line);
            self.in_colors = false;
            self.bar_has_colors = true;
            return;
        }
        let bar = match self.theme.bar_colors.as_ref() {
            Some(b) => b,
            None => {
                // Without bar colours in the theme the block is left alone.
                self.emit_line(line);
                return;
            }
        };
        if SINGLE_KEYS.contains(&first) {
            self.colors_seen.push(first.to_string());
            self.emit(&format!("{}{} ", indent, first));
            let value = match bar.single(first) {
                Some(c) => c.clone(),
                None => tokens[1].to_string(),
            };
            self.emit_line(&value);
            return;
        }
        if WORKSPACE_CLASSES.contains(&first) {
            self.colors_seen.push(first.to_string());
            let ws = match bar.workspace(first) {
                Some(ws) => ws.clone(),
                None => {
                    self.emit_line(line);
                    return;
                }
            };
            self.emit(&format!("{}{} ", indent, first));
            let border = match &ws.border {
                Some(b) => b.clone(),
                None => tokens[1].to_string(),
            };
            self.emit(&format!("{} ", border));
            let background = match &ws.background {
                Some(b) => b.clone(),
                None => tokens[2].to_string(),
            };
            self.emit(&format!("{} ", background));
            let text = match &ws.text {
                Some(t) => t.clone(),
                None => tokens[3].to_string(),
            };
            self.emit(&text);
            let extra = match &ws.indicator {
                Some(i) => Some(i.clone()),
                None => tokens.get(3).map(|s| s.to_string()),
            };
            if let Some(e) = extra {
                self.emit(&format!(" {}", e));
            }
            self.emit("\n");
            return;
        }
        // Anything else inside the colors block is dropped.
    }

    fn handle_client_line(&mut self, line: &str, class: &str, tokens: &[&str]) {
        self.clients_seen.push(class.to_string());
        let wc = match self.theme.window_colors.as_ref().and_then(|w| w.get(class)) {
            Some(wc) => wc.clone(),
            None => {
                self.emit_line(line);
                return;
            }
        };
        let indent = indent_of(line);
        self.emit(&format!("{}client.{} ", indent, class));
        let border = match &wc.border {
            Some(b) => b.clone(),
            None => tokens[1].to_string(),
        };
        self.emit(&format!("{} ", border));
        let background = match &wc.background {
            Some(b) => b.clone(),
            None => tokens[2].to_string(),
        };
        self.emit(&format!("{} ", background));
        let text = match &wc.text {
            Some(t) => Some(t.clone()),
            None => tokens.get(3).map(|s| s.to_string()),
        };
        if let Some(t) = text {
            self.emit(&format!("{} ", t));
            let indicator = match &wc.indicator {
                Some(i) => i.clone(),
                None => tokens.get(4).map(|s| s.to_string()).unwrap_or_default(),
            };
            self.emit(&indicator);
        }
        self.emit("\n");
    }

    pub fn apply(&mut self, config: &str) {
        for line in config.lines() {
            let tokens = words(line);
            let first = tokens.first().copied();
            if self.in_colors {
                match first {
                    None => self.emit_line(line),
                    Some(_) => self.handle_colors_line(line, &tokens),
                }
                continue;
            }
            if self.in_bar {
                match first {
                    Some("colors") => {
                        self.in_colors = true;
                        self.colors_seen.clear();
                        self.emit_line(line);
                    }
                    Some("}") => {
                        if !self.bar_has_colors {
                            self.new_colors_block();
                        }
                        self.in_bar = false;
                        self.bar_has_colors = false;
                        self.emit_line(line);
                    }
                    Some(f) if f.starts_with("client.") && WINDOW_CLASSES.contains(&&f[7..]) => {
                        self.handle_client_line(line, &f[7..], &tokens);
                    }
                    _ => self.emit_line(line),
                }
                continue;
            }
            match first {
                Some("bar") => {
                    self.in_bar = true;
                    self.emit_line(line);
                }
                Some(f) if f.starts_with("client.") && WINDOW_CLASSES.contains(&&f[7..]) => {
                    self.handle_client_line(line, &f[7..], &tokens);
                }
                _ => self.emit_line(line),
            }
        }
        self.append_clients();
    }

    /// Add `client.*` lines for the window classes the config did not have.
    fn append_clients(&mut self) {
        let missing: Vec<&str> = WINDOW_CLASSES
            .iter()
            .copied()
            .filter(|c| !self.clients_seen.iter().any(|s| s == c))
            .collect();
        for class in missing {
            let wc = self.theme.window_colors.as_ref().unwrap().get(class).cloned();
            if let Some(wc) = wc {
                let b = wc.border.as_deref().unwrap_or(BLACK);
                let bg = wc.background.as_deref().unwrap_or(BLACK);
                let t = wc.text.as_deref().unwrap_or(BLACK);
                let mut out = format!("client.{} {} {} {}", class, b, bg, t);
                if let Some(i) = &wc.indicator {
                    out.push(' ');
                    out.push_str(i);
                }
                self.emit_line(&out);
            }
        }
    }
}

pub fn apply_theme<'a>(theme: &'a Theme, config: &str, out: &'a mut Sink<'a>) {
    let mut applier = Applier::new(theme, out);
    applier.apply(config);
}
