//! A small YAML reader/writer that covers the subset of YAML used by theme
//! files.  The data model mirrors the one used by the classic `yaml-rust`
//! crate: plain scalars are typed (null / bool / integer / real / string),
//! quoted scalars are always strings, and mappings keep insertion order.

use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum Yaml {
    Real(String),
    Integer(i64),
    String(String),
    Boolean(bool),
    Array(Vec<Yaml>),
    Hash(Vec<(Yaml, Yaml)>),
    Alias(String),
    Null,
    BadValue,
}

static BAD_VALUE: Yaml = Yaml::BadValue;

impl Yaml {
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Yaml::String(s) => Some(s),
            _ => None,
        }
    }

    pub fn as_hash(&self) -> Option<&Vec<(Yaml, Yaml)>> {
        match self {
            Yaml::Hash(h) => Some(h),
            _ => None,
        }
    }

    /// Look a key up in a mapping.  Anything that is not a mapping (or a
    /// missing key) yields `BadValue`, just like indexing in yaml-rust.
    pub fn get(&self, key: &str) -> &Yaml {
        if let Yaml::Hash(h) = self {
            for (k, v) in h {
                if let Yaml::String(ks) = k {
                    if ks == key {
                        return v;
                    }
                }
            }
        }
        &BAD_VALUE
    }

    /// Build a scalar from a plain (unquoted) scalar text.
    pub fn from_plain(v: &str) -> Yaml {
        if let Some(rest) = v.strip_prefix("0x") {
            if let Ok(i) = i64::from_str_radix(rest, 16) {
                return Yaml::Integer(i);
            }
        }
        if let Some(rest) = v.strip_prefix("0o") {
            if let Ok(i) = i64::from_str_radix(rest, 8) {
                return Yaml::Integer(i);
            }
        }
        if let Some(rest) = v.strip_prefix('+') {
            if let Ok(i) = rest.parse::<i64>() {
                return Yaml::Integer(i);
            }
        }
        match v {
            "~" | "null" => Yaml::Null,
            "true" => Yaml::Boolean(true),
            "false" => Yaml::Boolean(false),
            _ if v.parse::<i64>().is_ok() => Yaml::Integer(v.parse().unwrap()),
            _ if parse_real(v).is_some() => Yaml::Real(v.to_owned()),
            _ => Yaml::String(v.to_owned()),
        }
    }
}

fn parse_real(v: &str) -> Option<f64> {
    match v {
        ".inf" | ".Inf" | ".INF" | "+.inf" | "+.Inf" | "+.INF" => Some(f64::INFINITY),
        "-.inf" | "-.Inf" | "-.INF" => Some(f64::NEG_INFINITY),
        ".nan" | "NaN" | ".NAN" => Some(f64::NAN),
        _ => v.parse::<f64>().ok(),
    }
}

fn hash_insert(h: &mut Vec<(Yaml, Yaml)>, k: Yaml, v: Yaml) {
    for entry in h.iter_mut() {
        if entry.0 == k {
            entry.1 = v;
            return;
        }
    }
    h.push((k, v));
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub struct Marker {
    pub index: usize,
    pub line: usize,
    pub col: usize,
}

#[derive(Clone)]
pub struct ScanError {
    pub mark: Marker,
    pub info: String,
}

impl fmt::Debug for ScanError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "ScanError {{ mark: Marker {{ index: {}, line: {}, col: {} }}, info: {:?} }}",
            self.mark.index, self.mark.line, self.mark.col, self.info
        )
    }
}

impl fmt::Display for ScanError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(self, f)
    }
}

type Res<T> = Result<T, ScanError>;

const E_KEY: &str = "while parsing a block mapping, did not find expected key";
const E_DASH: &str = "while parsing a block collection, did not find expected '-' indicator";
const E_DOCSTART: &str = "did not find expected <document start>";
const E_CONTENT: &str = "while parsing a node, did not find expected node content";
const E_MAPVAL: &str = "mapping values are not allowed in this context";
const E_MAPKEY: &str = "mapping keys are not allowed in this context";
const E_SEQENTRY: &str = "block sequence entries are not allowed in this context";
const E_ANCHOR: &str = "while scanning an anchor or alias, did not find expected alphabetic or numeric character";
const E_UNKNOWN_ANCHOR: &str = "while parsing node, found unknown anchor";
const E_TAB: &str = "while scanning a plain scalar, found a tab";
const E_QEOF: &str = "while scanning a quoted scalar, found unexpected end of stream";
const E_QESC: &str = "while parsing a quoted scalar, found unknown escape character";
const E_FLOWSEQ: &str = "while parsing a flow sequence, expected ',' or ']'";
const E_FLOWMAP: &str = "while parsing a flow mapping, did not find expected ',' or '}'";
const E_DIRECTIVE: &str = "while scanning a YAML directive, did not find expected version number";

/// What surrounds the node being parsed; used to pick error messages.
#[derive(Clone, Copy, PartialEq)]
enum Ctx {
    Document,
    Mapping,
    Sequence,
}

fn junk_error(ctx: Ctx) -> &'static str {
    match ctx {
        Ctx::Document => E_DOCSTART,
        Ctx::Mapping => E_KEY,
        Ctx::Sequence => E_DASH,
    }
}

// ---------------------------------------------------------------------------
// Reader
// ---------------------------------------------------------------------------

struct Reader {
    chars: Vec<char>,
    /// byte offset of every char (plus one trailing entry for the end)
    offsets: Vec<usize>,
    pos: usize,
    anchors: Vec<(String, Yaml)>,
}

fn is_blank(c: Option<char>) -> bool {
    matches!(c, None | Some(' ') | Some('\t') | Some('\n') | Some('\r'))
}

fn is_space(c: Option<char>) -> bool {
    matches!(c, Some(' ') | Some('\t'))
}

fn is_break(c: Option<char>) -> bool {
    matches!(c, None | Some('\n') | Some('\r'))
}

impl Reader {
    fn new(src: &str) -> Reader {
        let mut chars = Vec::new();
        let mut offsets = Vec::new();
        for (i, c) in src.char_indices() {
            chars.push(c);
            offsets.push(i);
        }
        offsets.push(src.len());
        Reader { chars, offsets, pos: 0, anchors: Vec::new() }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<char> {
        self.chars.get(self.pos + off).copied()
    }

    fn at(&self, pos: usize) -> Option<char> {
        self.chars.get(pos).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn at_end(&self) -> bool {
        self.pos >= self.chars.len()
    }

    fn marker_at(&self, pos: usize) -> Marker {
        let pos = pos.min(self.chars.len());
        let mut line = 1;
        let mut col = 0;
        for &c in &self.chars[..pos] {
            if c == '\n' {
                line += 1;
                col = 0;
            } else {
                col += 1;
            }
        }
        if pos == self.chars.len() && col != 0 {
            // the end of the stream always starts a fresh line
            line += 1;
            col = 0;
        }
        Marker { index: self.offsets[pos], line, col }
    }

    fn error<T>(&self, pos: usize, info: &str) -> Res<T> {
        Err(ScanError { mark: self.marker_at(pos), info: info.to_string() })
    }

    /// Column (0-based) of the current position within its line.
    fn column(&self) -> usize {
        let mut col = 0;
        let mut p = self.pos;
        while p > 0 && self.chars[p - 1] != '\n' {
            p -= 1;
            col += 1;
        }
        col
    }

    fn at_line_start(&self) -> bool {
        self.pos == 0 || self.chars[self.pos - 1] == '\n'
    }

    fn skip_spaces(&mut self) {
        while is_space(self.peek()) {
            self.pos += 1;
        }
    }

    fn skip_comment(&mut self) {
        if let Some('#') = self.peek() {
            while let Some(c) = self.peek() {
                if c == '\n' {
                    break;
                }
                self.pos += 1;
            }
        }
    }

    fn skip_newline(&mut self) {
        if let Some('\r') = self.peek() {
            self.pos += 1;
        }
        if let Some('\n') = self.peek() {
            self.pos += 1;
        }
    }

    /// After an inline node: only blanks and a comment may follow on the
    /// line.  Anything else is reported with a context specific message.
    fn finish_line(&mut self, ctx: Ctx) -> Res<()> {
        self.skip_spaces();
        match self.peek() {
            None | Some('\n') | Some('\r') | Some('#') => {
                self.skip_comment();
                self.skip_newline();
                Ok(())
            }
            Some(':') if is_blank(self.peek_at(1)) => self.error(self.pos, E_MAPVAL),
            _ => self.error(self.pos, junk_error(ctx)),
        }
    }

    /// Skip blank lines and comment lines.  Leaves the cursor at the start of
    /// the first line that has content or at the end of input.
    fn skip_blank_lines(&mut self) {
        loop {
            let save = self.pos;
            self.skip_spaces();
            match self.peek() {
                None => return,
                Some('\n') | Some('\r') => self.skip_newline(),
                Some('#') => {
                    self.skip_comment();
                    self.skip_newline();
                }
                _ => {
                    self.pos = save;
                    return;
                }
            }
        }
    }

    /// Indentation (number of leading blanks) of the line at the cursor,
    /// assuming the cursor is at a line start.
    fn line_indent(&self) -> usize {
        let mut n = 0;
        while is_space(self.chars.get(self.pos + n).copied()) {
            n += 1;
        }
        n
    }

    fn starts_with(&self, s: &str) -> bool {
        let mut i = self.pos;
        for c in s.chars() {
            if self.chars.get(i) != Some(&c) {
                return false;
            }
            i += 1;
        }
        true
    }

    fn is_document_marker(&self) -> bool {
        if !self.at_line_start() {
            return false;
        }
        (self.starts_with("---") || self.starts_with("...")) && is_blank(self.peek_at(3))
    }

    fn is_directive(&self) -> bool {
        self.at_line_start() && self.peek() == Some('%')
    }

    fn anchor(&self, name: &str) -> Option<Yaml> {
        self.anchors.iter().rev().find(|(n, _)| n == name).map(|(_, v)| v.clone())
    }
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

/// Parse every document in `src`.  Returns an empty vector when the input
/// contains no documents (e.g. it is empty or only has comments).
pub fn load_from_str(src: &str) -> Res<Vec<Yaml>> {
    let mut r = Reader::new(src);
    let mut docs = Vec::new();
    loop {
        r.skip_blank_lines();
        if r.at_end() {
            break;
        }
        // directives
        let mut had_directive = false;
        while r.is_directive() {
            parse_directive(&mut r)?;
            had_directive = true;
            r.skip_blank_lines();
        }
        if had_directive && !(r.is_document_marker() && r.starts_with("---")) {
            return r.error(r.pos, E_DOCSTART);
        }
        if r.is_document_marker() && r.starts_with("...") {
            r.pos += 3;
            r.finish_line(Ctx::Document)?;
            // after an explicit end only a new document start may follow
            r.skip_blank_lines();
            while r.is_directive() {
                parse_directive(&mut r)?;
                r.skip_blank_lines();
            }
            if r.at_end() {
                break;
            }
            if !(r.is_document_marker() && r.starts_with("---")) {
                return unexpected_document_content(&r);
            }
        }
        let mut explicit = false;
        if r.is_document_marker() && r.starts_with("---") {
            r.pos += 3;
            explicit = true;
            r.skip_spaces();
        }
        r.anchors.clear();
        let doc = if explicit && !is_break(r.peek()) && r.peek() != Some('#') {
            parse_value(&mut r, -1, Ctx::Document)?
        } else {
            if explicit {
                r.skip_comment();
                r.skip_newline();
            }
            r.skip_blank_lines();
            if r.at_end() || r.is_document_marker() {
                if explicit {
                    docs.push(Yaml::Null);
                }
                continue;
            }
            parse_block_node(&mut r, -1, Ctx::Document)?
        };
        docs.push(doc);
        // After a document only blank lines, comments or a marker may follow.
        r.skip_blank_lines();
        if !r.at_end() && !r.is_document_marker() && !r.is_directive() {
            return unexpected_document_content(&r);
        }
    }
    Ok(docs)
}

fn unexpected_document_content<T>(r: &Reader) -> Res<T> {
    // a mapping line is reported at its ':'
    let p = r.pos + r.line_indent();
    let mut tmp = Reader { chars: r.chars.clone(), offsets: r.offsets.clone(), pos: p, anchors: Vec::new() };
    tmp.pos = p;
    if let Some(c) = find_mapping_colon(&tmp) {
        return r.error(c, E_DOCSTART);
    }
    r.error(p, E_DOCSTART)
}

fn parse_directive(r: &mut Reader) -> Res<()> {
    let start = r.pos;
    r.pos += 1; // '%'
    let mut name = String::new();
    while let Some(c) = r.peek() {
        if is_blank(Some(c)) {
            break;
        }
        name.push(c);
        r.pos += 1;
    }
    if name == "YAML" {
        r.skip_spaces();
        let mut ok = false;
        let mut saw_dot = false;
        let mut digits_before = 0;
        let mut digits_after = 0;
        while let Some(c) = r.peek() {
            if c.is_ascii_digit() {
                if saw_dot {
                    digits_after += 1;
                } else {
                    digits_before += 1;
                }
                r.pos += 1;
            } else if c == '.' && !saw_dot {
                saw_dot = true;
                r.pos += 1;
            } else {
                break;
            }
        }
        if saw_dot && digits_before > 0 && digits_after > 0 {
            ok = true;
        }
        if !ok {
            return r.error(start, E_DIRECTIVE);
        }
    }
    // skip the rest of the line
    while let Some(c) = r.peek() {
        if c == '\n' {
            break;
        }
        r.pos += 1;
    }
    r.skip_newline();
    Ok(())
}

fn is_sequence_entry(r: &Reader) -> bool {
    r.peek() == Some('-') && is_blank(r.peek_at(1))
}

fn is_complex_key(r: &Reader) -> bool {
    r.peek() == Some('?') && is_blank(r.peek_at(1))
}

/// Determine whether the line at the cursor is `key: value` (block mapping).
fn line_is_mapping_entry(r: &Reader) -> bool {
    find_mapping_colon(r).is_some()
}

/// Find the position of the `:` that separates key and value on the current
/// line, if any.  Handles quoted keys and flow-collection keys.
fn find_mapping_colon(r: &Reader) -> Option<usize> {
    let mut i = r.pos;
    let first = r.at(i)?;
    if first == '"' || first == '\'' {
        let q = first;
        i += 1;
        loop {
            match r.at(i) {
                None | Some('\n') => return None,
                Some(c) if c == q => {
                    if q == '\'' && r.at(i + 1) == Some('\'') {
                        i += 2;
                        continue;
                    }
                    i += 1;
                    break;
                }
                Some('\\') if q == '"' => i += 2,
                _ => i += 1,
            }
        }
        while is_space(r.at(i)) {
            i += 1;
        }
        if r.at(i) == Some(':') && is_blank(r.at(i + 1)) {
            return Some(i);
        }
        return None;
    }
    if first == '[' || first == '{' {
        let mut depth = 0;
        loop {
            match r.at(i) {
                None | Some('\n') => return None,
                Some('[') | Some('{') => depth += 1,
                Some(']') | Some('}') => {
                    depth -= 1;
                    if depth == 0 {
                        i += 1;
                        break;
                    }
                }
                _ => {}
            }
            i += 1;
        }
        while is_space(r.at(i)) {
            i += 1;
        }
        if r.at(i) == Some(':') && is_blank(r.at(i + 1)) {
            return Some(i);
        }
        return None;
    }
    if first == '#' {
        return None;
    }
    // plain key: scan until ": " or ":" at end of line; stop at " #"
    let mut prev_blank = true;
    while let Some(c) = r.at(i) {
        if c == '\n' || c == '\r' {
            return None;
        }
        if c == '#' && prev_blank {
            return None;
        }
        if c == ':' && is_blank(r.at(i + 1)) {
            return Some(i);
        }
        prev_blank = c == ' ' || c == '\t';
        i += 1;
    }
    None
}

/// Parse a node that starts on the current line (cursor is at a line start).
/// `parent_indent` is the indentation of the enclosing collection (-1 at the
/// top level).
fn parse_block_node(r: &mut Reader, parent_indent: i64, ctx: Ctx) -> Res<Yaml> {
    r.skip_blank_lines();
    if r.at_end() || r.is_document_marker() {
        return Ok(Yaml::Null);
    }
    let indent = r.line_indent() as i64;
    if indent <= parent_indent {
        return Ok(Yaml::Null);
    }
    r.pos += indent as usize;
    let indent = indent as usize;
    if is_sequence_entry(r) {
        return parse_block_sequence(r, indent);
    }
    if is_complex_key(r) || line_is_mapping_entry(r) {
        return parse_block_mapping(r, indent);
    }
    parse_value(r, parent_indent, ctx)
}

fn parse_block_sequence(r: &mut Reader, indent: usize) -> Res<Yaml> {
    let mut items = Vec::new();
    loop {
        // cursor is at the '-' of an entry
        r.pos += 1;
        r.skip_spaces();
        let item = if is_break(r.peek()) || r.peek() == Some('#') {
            r.skip_comment();
            r.skip_newline();
            parse_block_node(r, indent as i64, Ctx::Sequence)?
        } else {
            let col = r.column();
            if is_sequence_entry(r) {
                parse_block_sequence(r, col)?
            } else if is_complex_key(r) || line_is_mapping_entry(r) {
                parse_block_mapping(r, col)?
            } else {
                parse_value(r, indent as i64, Ctx::Sequence)?
            }
        };
        items.push(item);
        // next entry?
        r.skip_blank_lines();
        if r.at_end() || r.is_document_marker() {
            break;
        }
        let next_indent = r.line_indent();
        if next_indent < indent {
            break;
        }
        let p = r.pos + next_indent;
        if next_indent > indent {
            return r.error(p, E_DASH);
        }
        r.pos += indent;
        if !is_sequence_entry(r) {
            return r.error(r.pos, E_DASH);
        }
    }
    Ok(Yaml::Array(items))
}

fn parse_block_mapping(r: &mut Reader, indent: usize) -> Res<Yaml> {
    let mut hash: Vec<(Yaml, Yaml)> = Vec::new();
    loop {
        // cursor is at the first char of the key
        let (key, value) = if is_complex_key(r) {
            r.pos += 1;
            r.skip_spaces();
            let key = if is_break(r.peek()) || r.peek() == Some('#') {
                r.skip_comment();
                r.skip_newline();
                parse_block_node(r, indent as i64, Ctx::Mapping)?
            } else {
                parse_value(r, indent as i64, Ctx::Mapping)?
            };
            // optional ": value" line at the same indentation
            r.skip_blank_lines();
            let mut value = Yaml::Null;
            if !r.at_end() && !r.is_document_marker() && r.line_indent() == indent {
                let save = r.pos;
                r.pos += indent;
                if r.peek() == Some(':') && is_blank(r.peek_at(1)) {
                    r.pos += 1;
                    r.skip_spaces();
                    value = if is_break(r.peek()) || r.peek() == Some('#') {
                        r.skip_comment();
                        r.skip_newline();
                        parse_block_node(r, indent as i64, Ctx::Mapping)?
                    } else {
                        parse_value(r, indent as i64, Ctx::Mapping)?
                    };
                } else {
                    r.pos = save;
                }
            }
            (key, value)
        } else {
            let colon = match find_mapping_colon(r) {
                Some(c) => c,
                None => return r.error(r.pos, E_KEY),
            };
            let key = parse_key(r, colon)?;
            r.pos = colon + 1;
            r.skip_spaces();
            let value = if is_break(r.peek()) || r.peek() == Some('#') {
                r.skip_comment();
                r.skip_newline();
                // block value on following lines; a sequence may sit at the
                // same indentation as the key.
                r.skip_blank_lines();
                if !r.at_end() && !r.is_document_marker() {
                    let ni = r.line_indent();
                    if ni == indent {
                        let save = r.pos;
                        r.pos += ni;
                        if is_sequence_entry(r) {
                            parse_block_sequence(r, indent)?
                        } else {
                            r.pos = save;
                            Yaml::Null
                        }
                    } else {
                        parse_block_node(r, indent as i64, Ctx::Mapping)?
                    }
                } else {
                    Yaml::Null
                }
            } else {
                parse_value(r, indent as i64, Ctx::Mapping)?
            };
            (key, value)
        };
        hash_insert(&mut hash, key, value);
        // next entry?
        r.skip_blank_lines();
        if r.at_end() || r.is_document_marker() {
            break;
        }
        let next_indent = r.line_indent();
        if next_indent < indent {
            break;
        }
        let p = r.pos + next_indent;
        if next_indent > indent {
            let mut tmp = Reader { chars: Vec::new(), offsets: Vec::new(), pos: p, anchors: Vec::new() };
            std::mem::swap(&mut tmp.chars, &mut r.chars);
            std::mem::swap(&mut tmp.offsets, &mut r.offsets);
            let colon = find_mapping_colon(&tmp);
            std::mem::swap(&mut tmp.chars, &mut r.chars);
            std::mem::swap(&mut tmp.offsets, &mut r.offsets);
            return r.error(colon.unwrap_or(p), E_KEY);
        }
        r.pos += indent;
        if !is_complex_key(r) && !line_is_mapping_entry(r) {
            return r.error(r.pos, E_KEY);
        }
    }
    Ok(Yaml::Hash(hash))
}

fn parse_key(r: &mut Reader, colon: usize) -> Res<Yaml> {
    let c = r.peek().unwrap_or(' ');
    if c == '"' {
        return Ok(Yaml::String(parse_double_quoted(r)?));
    }
    if c == '\'' {
        return Ok(Yaml::String(parse_single_quoted(r)?));
    }
    if c == '[' || c == '{' {
        return parse_flow_collection(r);
    }
    let text: String = r.chars[r.pos..colon].iter().collect();
    let text = text.trim_end().to_string();
    r.pos = colon;
    Ok(Yaml::from_plain(&text))
}

/// Node properties (`&anchor`, `!tag`) that may precede a node.
#[derive(Default)]
struct Props {
    anchor: Option<String>,
    tag: Option<String>,
}

fn parse_props(r: &mut Reader, ctx: Ctx) -> Res<Props> {
    let mut props = Props::default();
    loop {
        match r.peek() {
            Some('&') => {
                if props.anchor.is_some() {
                    return r.error(r.pos, junk_error(ctx));
                }
                let start = r.pos;
                r.pos += 1;
                let mut name = String::new();
                while let Some(c) = r.peek() {
                    if c.is_alphanumeric() || c == '-' || c == '_' {
                        name.push(c);
                        r.pos += 1;
                    } else {
                        break;
                    }
                }
                if name.is_empty() {
                    return r.error(start, E_ANCHOR);
                }
                props.anchor = Some(name);
                r.skip_spaces();
            }
            Some('!') => {
                if props.tag.is_some() {
                    return r.error(r.pos, junk_error(ctx));
                }
                let mut tag = String::new();
                while let Some(c) = r.peek() {
                    if is_blank(Some(c)) {
                        break;
                    }
                    tag.push(c);
                    r.pos += 1;
                }
                props.tag = Some(tag);
                r.skip_spaces();
            }
            _ => return Ok(props),
        }
    }
}

fn apply_tag(node: Yaml, tag: &Option<String>, plain: bool) -> Yaml {
    let tag = match tag {
        Some(t) => t,
        None => return node,
    };
    if !plain {
        return node;
    }
    let text = match &node {
        Yaml::String(s) => s.clone(),
        Yaml::Integer(i) => i.to_string(),
        Yaml::Real(s) => s.clone(),
        Yaml::Boolean(b) => b.to_string(),
        Yaml::Null => "~".to_string(),
        _ => return node,
    };
    match tag.as_str() {
        "!!str" => Yaml::String(text),
        "!!int" => text.parse::<i64>().map(Yaml::Integer).unwrap_or(Yaml::BadValue),
        "!!float" => parse_real(&text).map(|_| Yaml::Real(text.clone())).unwrap_or(Yaml::BadValue),
        "!!bool" => match text.as_str() {
            "true" => Yaml::Boolean(true),
            "false" => Yaml::Boolean(false),
            _ => Yaml::BadValue,
        },
        "!!null" => match text.as_str() {
            "~" | "null" => Yaml::Null,
            _ => Yaml::BadValue,
        },
        _ => Yaml::String(text),
    }
}

/// Parse an inline node that begins at the cursor: properties, then a quoted
/// scalar, a flow collection, an alias, a block scalar, or a plain scalar
/// (which may be folded over continuation lines indented deeper than
/// `indent`).  When the properties are followed by a line break, the node is
/// the block node on the following lines.
fn parse_value(r: &mut Reader, indent: i64, ctx: Ctx) -> Res<Yaml> {
    let props = parse_props(r, ctx)?;
    if is_break(r.peek()) || r.peek() == Some('#') {
        r.skip_comment();
        r.skip_newline();
        let node = if props.anchor.is_some() || props.tag.is_some() {
            parse_block_node(r, indent, ctx)?
        } else {
            Yaml::Null
        };
        let node = apply_tag(node, &props.tag, matches!(node, Yaml::Null));
        if let Some(a) = props.anchor {
            r.anchors.push((a, node.clone()));
        }
        return Ok(node);
    }
    let (node, plain) = match r.peek() {
        Some('"') => {
            let s = parse_double_quoted(r)?;
            r.finish_line(ctx)?;
            (Yaml::String(s), false)
        }
        Some('\'') => {
            let s = parse_single_quoted(r)?;
            r.finish_line(ctx)?;
            (Yaml::String(s), false)
        }
        Some('[') | Some('{') => {
            let node = parse_flow_collection(r)?;
            r.finish_line(ctx)?;
            (node, false)
        }
        Some('*') => {
            let start = r.pos;
            r.pos += 1;
            let mut name = String::new();
            while let Some(c) = r.peek() {
                if c.is_alphanumeric() || c == '-' || c == '_' {
                    name.push(c);
                    r.pos += 1;
                } else {
                    break;
                }
            }
            if name.is_empty() {
                return r.error(start, E_ANCHOR);
            }
            let node = match r.anchor(&name) {
                Some(n) => n,
                None => return r.error(start, E_UNKNOWN_ANCHOR),
            };
            r.finish_line(ctx)?;
            (node, false)
        }
        Some('|') | Some('>') => (parse_block_scalar(r, indent)?, false),
        Some('@') | Some('`') | Some('%') => {
            let c = r.peek().unwrap();
            return r.error(r.pos, &format!("unexpected character: `{}'", c));
        }
        Some(',') | Some(']') | Some('}') => return r.error(r.pos, E_CONTENT),
        Some('-') if is_blank(r.peek_at(1)) => return r.error(r.pos, E_SEQENTRY),
        Some('?') if is_blank(r.peek_at(1)) => return r.error(r.pos, E_MAPKEY),
        Some(':') if is_blank(r.peek_at(1)) => return r.error(r.pos, E_MAPVAL),
        _ => (parse_plain(r, indent)?, true),
    };
    let node = apply_tag(node, &props.tag, plain);
    if let Some(a) = props.anchor {
        r.anchors.push((a, node.clone()));
    }
    Ok(node)
}

/// Plain scalar in block context, possibly spanning several lines.
fn parse_plain(r: &mut Reader, indent: i64) -> Res<Yaml> {
    let start = r.pos;
    let mut text = String::new();
    let mut pending_breaks = 0usize;
    loop {
        // scan one line of the scalar
        let mut end = r.pos;
        let mut i = r.pos;
        let mut prev_blank = false;
        while let Some(c) = r.at(i) {
            if c == '\n' || c == '\r' {
                break;
            }
            if c == '#' && prev_blank {
                break;
            }
            if c == ':' && is_blank(r.at(i + 1)) {
                return r.error(i, E_MAPVAL);
            }
            prev_blank = c == ' ' || c == '\t';
            i += 1;
            if !(c == ' ' || c == '\t') {
                end = i;
            }
        }
        let piece: String = r.chars[r.pos..end].iter().collect();
        if !piece.is_empty() {
            if !text.is_empty() {
                if pending_breaks == 0 {
                    text.push(' ');
                } else {
                    for _ in 0..pending_breaks {
                        text.push('\n');
                    }
                }
            }
            text.push_str(&piece);
        }
        pending_breaks = 0;
        r.pos = end;
        r.skip_spaces();
        r.skip_comment();
        let had_comment = r.pos > end && r.at(r.pos - 1) != Some(' ') && r.at(end) != Some('\n');
        r.skip_newline();
        if had_comment && r.at(end) == Some('#') {
            break;
        }
        // continuation line?
        let save = r.pos;
        let mut breaks = 0usize;
        loop {
            let p = r.pos + r.line_indent();
            match r.at(p) {
                Some('\n') | Some('\r') => {
                    r.pos = p;
                    r.skip_newline();
                    breaks += 1;
                }
                _ => break,
            }
        }
        if r.at_end() || r.is_document_marker() {
            r.pos = save;
            break;
        }
        let ni = r.line_indent() as i64;
        if ni <= indent {
            r.pos = save;
            break;
        }
        let p = r.pos + ni as usize;
        if r.at(p) == Some('#') {
            r.pos = save;
            break;
        }
        // tabs are not allowed as indentation of a continuation line
        let mut q = r.pos;
        while q < p {
            if r.at(q) == Some('\t') {
                return r.error(start, E_TAB);
            }
            q += 1;
        }
        r.pos = p;
        pending_breaks = breaks;
    }
    let _ = pending_breaks;
    Ok(Yaml::from_plain(&text))
}

fn parse_double_quoted(r: &mut Reader) -> Res<String> {
    let start = r.pos;
    r.pos += 1; // opening quote
    let mut out = String::new();
    loop {
        let c = match r.bump() {
            None => return r.error(start, E_QEOF),
            Some(c) => c,
        };
        match c {
            '"' => break,
            '\\' => {
                let e = match r.bump() {
                    None => return r.error(start, E_QEOF),
                    Some(e) => e,
                };
                match e {
                    '0' => out.push('\0'),
                    'a' => out.push('\x07'),
                    'b' => out.push('\x08'),
                    't' | '\t' => out.push('\t'),
                    'n' => out.push('\n'),
                    'v' => out.push('\x0b'),
                    'f' => out.push('\x0c'),
                    'r' => out.push('\r'),
                    'e' => out.push('\x1b'),
                    ' ' => out.push(' '),
                    '"' => out.push('"'),
                    '\'' => out.push('\''),
                    '\\' => out.push('\\'),
                    'N' => out.push('\u{85}'),
                    '_' => out.push('\u{a0}'),
                    'L' => out.push('\u{2028}'),
                    'P' => out.push('\u{2029}'),
                    'x' | 'u' | 'U' => {
                        let n = match e {
                            'x' => 2,
                            'u' => 4,
                            _ => 8,
                        };
                        let mut v: u32 = 0;
                        for _ in 0..n {
                            let h = match r.bump() {
                                Some(h) if h.is_ascii_hexdigit() => h,
                                _ => {
                                    return r.error(
                                        start,
                                        "while parsing a quoted scalar, did not find expected hexdecimal number",
                                    )
                                }
                            };
                            v = v * 16 + h.to_digit(16).unwrap();
                        }
                        match char::from_u32(v) {
                            Some(ch) => out.push(ch),
                            None => {
                                return r.error(
                                    start,
                                    "while parsing a quoted scalar, found invalid Unicode character escape code",
                                )
                            }
                        }
                    }
                    '\n' | '\r' => {
                        if e == '\r' && r.peek() == Some('\n') {
                            r.pos += 1;
                        }
                        while is_space(r.peek()) {
                            r.pos += 1;
                        }
                    }
                    _ => return r.error(start, E_QESC),
                }
            }
            '\n' | '\r' => {
                fold_quoted_break(r, &mut out, c);
            }
            c => out.push(c),
        }
    }
    Ok(out)
}

fn fold_quoted_break(r: &mut Reader, out: &mut String, c: char) {
    if c == '\r' && r.peek() == Some('\n') {
        r.pos += 1;
    }
    while is_space(r.peek()) {
        r.pos += 1;
    }
    let mut breaks = 0;
    while matches!(r.peek(), Some('\n') | Some('\r')) {
        if r.peek() == Some('\n') {
            breaks += 1;
        }
        r.pos += 1;
        while is_space(r.peek()) {
            r.pos += 1;
        }
    }
    let trimmed_len = out.trim_end_matches([' ', '\t']).len();
    out.truncate(trimmed_len);
    if breaks == 0 {
        out.push(' ');
    } else {
        for _ in 0..breaks {
            out.push('\n');
        }
    }
}

fn parse_single_quoted(r: &mut Reader) -> Res<String> {
    let start = r.pos;
    r.pos += 1;
    let mut out = String::new();
    loop {
        let c = match r.bump() {
            None => return r.error(start, E_QEOF),
            Some(c) => c,
        };
        match c {
            '\'' => {
                if r.peek() == Some('\'') {
                    r.pos += 1;
                    out.push('\'');
                } else {
                    break;
                }
            }
            '\n' | '\r' => fold_quoted_break(r, &mut out, c),
            c => out.push(c),
        }
    }
    Ok(out)
}

fn skip_flow_ws(r: &mut Reader) {
    loop {
        match r.peek() {
            Some(' ') | Some('\t') | Some('\n') | Some('\r') => r.pos += 1,
            Some('#') => r.skip_comment(),
            _ => return,
        }
    }
}

/// Parse `[...]` or `{...}` starting at the cursor (which is on the bracket).
fn parse_flow_collection(r: &mut Reader) -> Res<Yaml> {
    let open = r.bump().unwrap();
    let is_seq = open == '[';
    let close = if is_seq { ']' } else { '}' };
    let after_entry = if is_seq { E_FLOWSEQ } else { E_FLOWMAP };
    let mut items: Vec<Yaml> = Vec::new();
    let mut hash: Vec<(Yaml, Yaml)> = Vec::new();
    loop {
        skip_flow_ws(r);
        match r.peek() {
            None => return r.error(r.pos, E_CONTENT),
            Some(c) if c == close => {
                r.pos += 1;
                break;
            }
            Some(',') | Some(']') | Some('}') => return r.error(r.pos, E_CONTENT),
            _ => {}
        }
        // explicit key indicator
        let mut explicit_key = false;
        if r.peek() == Some('?') && is_blank(r.peek_at(1)) {
            r.pos += 1;
            skip_flow_ws(r);
            explicit_key = true;
        }
        let key_or_item = parse_flow_node(r)?;
        skip_flow_ws(r);
        if r.peek() == Some(':') {
            r.pos += 1;
            skip_flow_ws(r);
            let value = if matches!(r.peek(), Some(',') | Some(']') | Some('}')) {
                Yaml::Null
            } else {
                parse_flow_node(r)?
            };
            if is_seq {
                items.push(Yaml::Hash(vec![(key_or_item, value)]));
            } else {
                hash_insert(&mut hash, key_or_item, value);
            }
        } else if is_seq {
            if explicit_key {
                items.push(Yaml::Hash(vec![(key_or_item, Yaml::Null)]));
            } else {
                items.push(key_or_item);
            }
        } else {
            hash_insert(&mut hash, key_or_item, Yaml::Null);
        }
        skip_flow_ws(r);
        match r.peek() {
            Some(',') => r.pos += 1,
            Some(c) if c == close => {
                r.pos += 1;
                break;
            }
            _ => return r.error(r.pos, after_entry),
        }
    }
    if is_seq {
        Ok(Yaml::Array(items))
    } else {
        Ok(Yaml::Hash(hash))
    }
}

fn parse_flow_node(r: &mut Reader) -> Res<Yaml> {
    let props = parse_props(r, Ctx::Document)?;
    let (node, plain) = match r.peek() {
        Some('"') => (Yaml::String(parse_double_quoted(r)?), false),
        Some('\'') => (Yaml::String(parse_single_quoted(r)?), false),
        Some('[') | Some('{') => (parse_flow_collection(r)?, false),
        Some('*') => {
            let start = r.pos;
            r.pos += 1;
            let mut name = String::new();
            while let Some(c) = r.peek() {
                if c.is_alphanumeric() || c == '-' || c == '_' {
                    name.push(c);
                    r.pos += 1;
                } else {
                    break;
                }
            }
            if name.is_empty() {
                return r.error(start, E_ANCHOR);
            }
            match r.anchor(&name) {
                Some(n) => (n, false),
                None => return r.error(start, E_UNKNOWN_ANCHOR),
            }
        }
        Some('@') | Some('`') | Some('%') => {
            let c = r.peek().unwrap();
            return r.error(r.pos, &format!("unexpected character: `{}'", c));
        }
        _ => {
            let mut text = String::new();
            let mut prev_blank = true;
            while let Some(c) = r.peek() {
                if c == ',' || c == ']' || c == '}' || c == '[' || c == '{' {
                    break;
                }
                if c == ':' && (is_blank(r.peek_at(1)) || matches!(r.peek_at(1), Some(',') | Some(']') | Some('}'))) {
                    break;
                }
                if c == '#' && prev_blank {
                    break;
                }
                if c == '\n' || c == '\r' {
                    skip_flow_ws(r);
                    if !text.is_empty() && !text.ends_with(' ') {
                        text.push(' ');
                    }
                    prev_blank = true;
                    continue;
                }
                prev_blank = c == ' ' || c == '\t';
                text.push(c);
                r.pos += 1;
            }
            let t = text.trim_end();
            if t.is_empty() {
                (Yaml::Null, true)
            } else {
                (Yaml::from_plain(t), true)
            }
        }
    };
    let node = apply_tag(node, &props.tag, plain);
    if let Some(a) = props.anchor {
        r.anchors.push((a, node.clone()));
    }
    Ok(node)
}

fn parse_block_scalar(r: &mut Reader, indent: i64) -> Res<Yaml> {
    let style = r.bump().unwrap(); // '|' or '>'
    let mut chomp = 0i32; // 0 clip, -1 strip, +1 keep
    let mut explicit_indent: Option<usize> = None;
    loop {
        match r.peek() {
            Some('-') => {
                chomp = -1;
                r.pos += 1;
            }
            Some('+') => {
                chomp = 1;
                r.pos += 1;
            }
            Some(d) if d.is_ascii_digit() && d != '0' => {
                explicit_indent = Some(d.to_digit(10).unwrap() as usize);
                r.pos += 1;
            }
            _ => break,
        }
    }
    r.skip_spaces();
    r.skip_comment();
    r.skip_newline();
    let base = if indent < 0 { 0 } else { indent as usize };
    let mut lines: Vec<String> = Vec::new();
    let mut content_indent = explicit_indent.map(|n| base + n);
    loop {
        if r.at_end() {
            break;
        }
        let li = r.line_indent();
        let mut p = r.pos + li;
        if is_break(r.at(p)) {
            lines.push(String::new());
            while let Some(c) = r.at(p) {
                if c == '\n' {
                    break;
                }
                p += 1;
            }
            r.pos = p;
            r.skip_newline();
            continue;
        }
        if content_indent.is_none() {
            if (li as i64) <= indent {
                break;
            }
            content_indent = Some(li);
        }
        let ci = content_indent.unwrap();
        if li < ci || r.is_document_marker() {
            break;
        }
        let start = r.pos + ci;
        let mut end = start;
        while let Some(c) = r.at(end) {
            if c == '\n' || c == '\r' {
                break;
            }
            end += 1;
        }
        lines.push(r.chars[start..end].iter().collect());
        r.pos = end;
        r.skip_newline();
    }
    let mut trailing = 0;
    while trailing < lines.len() && lines[lines.len() - 1 - trailing].is_empty() {
        trailing += 1;
    }
    let body_len = lines.len() - trailing;
    let mut out = String::new();
    if style == '|' {
        for (i, l) in lines[..body_len].iter().enumerate() {
            out.push_str(l);
            if i + 1 < body_len {
                out.push('\n');
            }
        }
    } else {
        for i in 0..body_len {
            let l = &lines[i];
            if i > 0 {
                let prev = &lines[i - 1];
                if l.is_empty() {
                    out.push('\n');
                } else if prev.is_empty() || prev.starts_with(' ') || l.starts_with(' ') {
                    if !prev.is_empty() {
                        out.push('\n');
                    }
                } else {
                    out.push(' ');
                }
            }
            out.push_str(l);
        }
    }
    if body_len > 0 {
        match chomp {
            -1 => {}
            0 => out.push('\n'),
            _ => {
                out.push('\n');
                for _ in 0..trailing {
                    out.push('\n');
                }
            }
        }
    } else if chomp == 1 {
        for _ in 0..trailing {
            out.push('\n');
        }
    }
    Ok(Yaml::String(out))
}

