//! Applies a theme to an i3 configuration, rewriting the colour directives
//! while leaving everything else untouched.

use std::fs;
use std::io::{Read, Write};

use crate::theme::{words, Theme, WINDOW_CLASSES, WORKSPACE_CLASSES};

const SINGLE_KEYS: [&str; 3] = ["separator", "background", "statusline"];
const BLACK: &str = "#000000";

/// Leading whitespace of a line.
fn indent_of(line: &str) -> &str {
    let trimmed = line.trim_start();
    &line[..line.len() - trimmed.len()]
}

/// Read the whole configuration file.
///
/// Opening and reading are separate steps so that a missing file and an
/// unreadable one (for example a directory) fail at different points.
pub fn read_config(path: &str) -> String {
    let mut contents = String::new();
    let mut file = fs::File::open(path).unwrap();
    // The configuration has already been validated with `i3 -C` at this
    // point, so the file is expected to exist and be readable.  Should it
    // still be unreadable (a directory or a file with invalid UTF-8 for
    // instance) there is nothing sensible left to do with it.
    //
    // The whole file is read into memory at once: configurations are small
    // and the rewriting below works line by line on the in-memory text.
    //
    // Notes on the rewriting rules applied afterwards:
    //
    // * lines are split into words on single spaces; tabs are kept as part
    //   of the words, so `background<TAB>#000000` is not recognised;
    // * a `bar` block starts with a line whose first word is `bar` and ends
    //   with a line whose first word is `}`;
    // * inside a bar, a `colors` block starts with a line whose first word
    //   is `colors` and also ends with `}`;
    // * known colour directives are rewritten in place, unknown lines inside
    //   a `colors` block are dropped, and whatever the theme defines but the
    //   configuration lacks is appended.
    file.read_to_string(&mut contents).unwrap();
