//! i3-style: apply colour themes to an i3 configuration file.
//!
//! The tool reads an i3 configuration, validates it with `i3 -C`, rewrites
//! the window and bar colour directives according to a theme and either
//! prints the result or writes it back to disk.  It can also do the reverse
//! and derive a shareable theme from an existing configuration.

mod cli;
mod theme;
mod writer;
mod yaml;

use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{self, Command};
use std::time::{SystemTime, UNIX_EPOCH};

use theme::{Theme, BUILTIN_THEMES};

/// Payload used to report failures that originate in a colour library with
/// the location of that library's source.
pub struct FakePanic {
    pub file: &'static str,
    pub line: u32,
    pub col: u32,
    pub msg: String,
}

pub fn fail_at(file: &'static str, line: u32, col: u32, msg: String) -> ! {
    std::panic::panic_any(FakePanic { file, line, col, msg })
}

/// Install a panic hook that knows how to print `FakePanic` payloads in the
/// same format as the standard hook, and defers to it for everything else.
fn install_panic_hook() {
    let default = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        if let Some(fp) = info.payload().downcast_ref::<FakePanic>() {
            let _ = std::io::stdout().flush();
            eprintln!(
                "\nthread 'main' ({}) panicked at {}:{}:{}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
                process::id(), fp.file, fp.line, fp.col, fp.msg
            );
        } else {
            default(info);
        }
    }));
}

/// Locate the i3 config in the usual places: `~/.i3/config` first, then
/// `~/.config/i3/config`.
fn find_default_config() -> Option<String> {
    let home_dir_env = std::env::var("HOME").unwrap();
    let candidates = [
        format!("{}/.i3/config", home_dir_env),
        format!("{}/.config/i3/config", home_dir_env),
    ];
    for c in candidates {
        if Path::new(&c).exists() {
            return Some(c);
        }
    }
    None
}

/// The configuration to work on: the `--config` argument or the default
/// location.  Exits when no configuration can be found.
fn resolve_config(given: &Option<String>) -> String {
    if let Some(c) = given {
        return c.clone();
    }
    match find_default_config() {
        Some(c) => c,
        None => {
            eprintln!("Could not find i3 config");
            process::exit(1);
        }
    }
}

/// Run `i3 -C` on the config to make sure it is valid before touching it.
/// Both a missing `i3` binary and a failed validation end the program.
fn validate_config(path: &str) {
    let result = Command::new("i3").arg("-C").arg("-c").arg(path).output();
    match result {
        Err(e) => {
            eprintln!(
                "Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}",
                path, e
            );
            process::exit(1);
        }
        Ok(out) => {
            if !out.status.success() {
                eprintln!(
                    "Could not validate config.\nUse `i3 -C -c {}` to see validation errors.",
                    path
                );
                process::exit(1);
            }
        }
    }
}

/// Print the names and descriptions of the bundled themes.
fn list_themes() {
    println!("\nAvailable themes:");
    println!();
    let width = BUILTIN_THEMES.iter().map(|(n, _)| n.len()).max().unwrap_or(0);
    for (name, src) in BUILTIN_THEMES {
        let docs = yaml::load_from_str(src).expect("Could not parse yaml for theme");
        let theme = Theme::from_yaml(&docs[0]);
        println!("  {:<w$} - {}", name, theme.description.unwrap_or_default(), w = width);
    }
}

/// Load a theme by name (bundled) or by path.
fn load_theme(name: &str) -> Theme {
    let theme_file_text = match theme::builtin_theme(name) {
        Some(src) => src.to_string(),
        None => match fs::read_to_string(name) {
            Ok(t) => t,
            Err(e) => {
                eprintln!(
                    "Could not open theme: {} - {}\n Use `i3-style --list-all` to see the available themes.",
                    name, e
                );
                process::exit(1);
            }
        },
    };
    let docs = yaml::load_from_str(&theme_file_text).expect("Could not parse yaml for theme");
    let document = docs[0].clone();
    Theme::from_yaml(&document)
}

/// Ask a running i3 to reload its configuration.
fn reload_i3() {
    if let Err(e) = Command::new("i3-msg").arg("reload").output() {
        eprintln!("Could not reload config with i3-msg: {}", e);
        process::exit(1);
    }
}

/// A fresh working directory below the system temporary directory, named
/// after the current time.
fn temp_workdir() -> PathBuf {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
    let stamp = now.as_secs() + now.subsec_millis() as u64;
    let mut dir = std::env::temp_dir();
    dir.push("i3-style");
    dir.push(stamp.to_string());
    dir
}

/// Name of the executable as invoked, for usage messages.
fn bin_name(argv: &[String]) -> String {
    argv.first()
        .and_then(|a| Path::new(a).file_name().map(|f| f.to_string_lossy().to_string()))
        .unwrap_or_else(|| cli::NAME.to_string())
}

/// Print the short usage shown when no theme was given.
fn print_theme_hint(argv: &[String]) {
    println!("USAGE:\n    {} [FLAGS] [OPTIONS] [theme]\n", bin_name(argv));
    println!("Select a theme as the first argument. Use `--list-all` to see the themes.");
}

/// `--to-theme`: derive a theme from a configuration and print it.
fn run_to_theme(matches: &cli::Matches) {
    let value = matches.to_theme.clone().unwrap_or_default();
    let path = if value.is_empty() { resolve_config(&matches.config) } else { value };
    validate_config(&path);
    theme::print_theme_for_config(&path);
}

/// Apply the theme and write the result to `out_path`.
///
/// The themed configuration is first written to a scratch directory (next to
/// a copy of the original configuration, for safety) and then copied to its
/// destination.
fn apply_to_file(theme: &Theme, config_text: &str, config_path: &str, out_path: &str) {
    let dir = temp_workdir();
    fs::create_dir_all(&dir).unwrap();
    let output_file = dir.join("config-output");
    let input_file = dir.join("config-input");
    {
        let mut f = fs::File::create(&output_file).unwrap();
        writer::apply_theme(theme, config_text, &mut writer::Sink::File(&mut f));
    }
    eprintln!("saving config at {} to {}", config_path, input_file.display());
    fs::copy(config_path, &input_file).unwrap();
    write_output(&output_file, out_path);
}

fn main() {
    install_panic_hook();
    let argv: Vec<String> = std::env::args().collect();
    let matches = match cli::parse(&argv) {
        Ok(m) => m,
        Err(exit) => {
            if exit.stdout {
                print!("{}", exit.message);
            } else {
                eprint!("{}", exit.message);
            }
            process::exit(exit.code);
        }
    };

    if matches.list_all {
        list_themes();
        return;
    }

    if matches.to_theme_given {
        run_to_theme(&matches);
        return;
    }

    let theme_name = match &matches.theme {
        Some(t) => t.clone(),
        None => {
            print_theme_hint(&argv);
            process::exit(1);
        }
    };

    let config_path = resolve_config(&matches.config);
    validate_config(&config_path);
    let theme = load_theme(&theme_name);
    let config_text = writer::read_config(&config_path);

    let output_path = if let Some(o) = &matches.output {
        Some(o.clone())
    } else if matches.save {
        Some(config_path.clone())
    } else {
        None
    };

    match output_path {
        Some(out_path) => apply_to_file(&theme, &config_text, &config_path, &out_path),
        None => writer::apply_theme(&theme, &config_text, &mut writer::Sink::Stdout),
    }

    if matches.reload {
        reload_i3();
    }
}

/// Copy the generated configuration to its final destination.
fn write_output(output_file: &Path, out_path: &str) {
    fs::copy(&output_file, &out_path).unwrap();
}
