            Ok(t) => t,
            Err(e) => {
                eprintln!(
                    "Could not open theme: {} - {}\n Use `i3-style --list-all` to see the available themes.",
                    name, e
                );
                process::exit(1);
            }
        },
    };
    let docs = yaml::load_from_str(&theme_file_text).expect("Could not parse yaml for theme");
    let document = docs[0].clone();
    Theme::from_yaml(&document)
}

/// Ask a running i3 to reload its configuration.
fn reload_i3() {
    if let Err(e) = Command::new("i3-msg").arg("reload").output() {
        eprintln!("Could not reload config with i3-msg: {}", e);
        process::exit(1);
    }
}

/// A fresh working directory below the system temporary directory, named
/// after the current time.
fn temp_workdir() -> PathBuf {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
    let stamp = now.as_secs() + now.subsec_millis() as u64;
    let mut dir = std::env::temp_dir();
    dir.push("i3-style");
    dir.push(stamp.to_string());
    dir
}

/// Name of the executable as invoked, for usage messages.
fn bin_name(argv: &[String]) -> String {
    argv.first()
        .and_then(|a| Path::new(a).file_name().map(|f| f.to_string_lossy().to_string()))
        .unwrap_or_else(|| cli::NAME.to_string())
}

/// Print the short usage shown when no theme was given.
fn print_theme_hint(argv: &[String]) {
    println!("USAGE:\n    {} [FLAGS] [OPTIONS] [theme]\n", bin_name(argv));
    println!("Select a theme as the first argument. Use `--list-all` to see the themes.");
}

/// `--to-theme`: derive a theme from a configuration and print it.
fn run_to_theme(matches: &cli::Matches) {
    let value = matches.to_theme.clone().unwrap_or_default();
    let path = if value.is_empty() { resolve_config(&matches.config) } else { value };
    validate_config(&path);
    theme::print_theme_for_config(&path);
}

/// Apply the theme and write the result to `out_path`.
///
/// The themed configuration is first written to a scratch directory (next to
/// a copy of the original configuration, for safety) and then copied to its
/// destination.
fn apply_to_file(theme: &Theme, config_text: &str, config_path: &str, out_path: &str) {
    let dir = temp_workdir();
    fs::create_dir_all(&dir).unwrap();
    let output_file = dir.join("config-output");
    let input_file = dir.join("config-input");
    {
        let mut f = fs::File::create(&output_file).unwrap();
        writer::apply_theme(theme, config_text, &mut writer::Sink::File(&mut f));
    }
    eprintln!("saving config at {} to {}", config_path, input_file.display());
    fs::copy(config_path, &input_file).unwrap();
    write_output(&output_file, out_path);
}

fn main() {
    install_panic_hook();
    let argv: Vec<String> = std::env::args().collect();
    let matches = match cli::parse(&argv) {
        Ok(m) => m,
        Err(exit) => {
            if exit.stdout {
                print!("{}", exit.message);
            } else {
                eprint!("{}", exit.message);
            }
            process::exit(exit.code);
        }
    };

    if matches.list_all {
        list_themes();
        return;
    }

    if matches.to_theme_given {
        run_to_theme(&matches);
        return;
    }

    let theme_name = match &matches.theme {
        Some(t) => t.clone(),
        None => {
            print_theme_hint(&argv);
            process::exit(1);
        }
    };

    let config_path = resolve_config(&matches.config);
    validate_config(&config_path);
    let theme = load_theme(&theme_name);
    let config_text = writer::read_config(&config_path);

    let output_path = if let Some(o) = &matches.output {
        Some(o.clone())
    } else if matches.save {
        Some(config_path.clone())
    } else {
        None
    };

    match output_path {
        Some(out_path) => apply_to_file(&theme, &config_text, &config_path, &out_path),
        None => writer::apply_theme(&theme, &config_text, &mut writer::Sink::Stdout),
    }

    if matches.reload {
        reload_i3();
    }
}

/// Copy the generated configuration to its final destination.
fn write_output(output_file: &Path, out_path: &str) {
    fs::copy(&output_file, &out_path).unwrap();
}
